PathwayData.put("data/reading_writing/units/L04U4.json",{"strand":"reading_writing","level":4,"cefr":"A2b","unit":4,"theme":"Markets and Money","essential_question":"How do people buy, sell and save?","schema_version":"1.0","core_words":["price","cost","cheap","expensive","coin","riyal","change","customer","seller","spend","budget","receipt","wallet","trade"],"recycled_words":["dates","honey","buy","sell","first","next","finally","play","stage direction","list","because","so","honest"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L04-U4-LS1","title":"Word Power: Markets and Money","lesson_type":"vocabulary","objectives":["read, say and use 14 words about markets and money and 3 Tier 2 words (compare, estimate, afford)","use antonym context clues (but, however, not, unlike, instead of) to work out the meaning of new words","talk about buying, selling and saving with the new words"],"objectives_ar":["قراءة ونطق واستخدام 14 كلمة عن الأسواق والمال و3 كلمات أكاديمية.","استخدام أدلة السياق بالأضداد لفهم معنى الكلمات الجديدة.","التحدث عن البيع والشراء والادخار بالكلمات الجديدة."],"success_criteria":["I can read and use the money words in sentences.","I can find an antonym clue and use it to guess a word's meaning.","I can explain the difference between cheap and expensive, spend and save."],"success_criteria_ar":["أستطيع قراءة كلمات المال واستخدامها في جمل.","أستطيع إيجاد دليل الضد واستخدامه لتخمين معنى الكلمة.","أستطيع شرح الفرق بين الرخيص والغالي، والإنفاق والادخار."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"price","pos":"noun","ipa":"/praɪs/","definition":"the amount of money you must pay for something","arabic":"سعر","example":"The price of the dates is 25 riyals.","image_id":"IMG-RW-L04-U4-LS1-V01","audio_id":"AUD-RW-L04-U4-LS1-V01","tier":"core"},{"word":"cost","pos":"verb / noun","ipa":"/kɔst/","definition":"to have a price; the amount you pay","arabic":"يكلّف / تكلفة","example":"How much does this lantern cost?","image_id":"IMG-RW-L04-U4-LS1-V02","audio_id":"AUD-RW-L04-U4-LS1-V02","tier":"core"},{"word":"cheap","pos":"adjective","ipa":"/tʃip/","definition":"not costing much money","arabic":"رخيص","example":"This pen is cheap – only 2 riyals.","image_id":"IMG-RW-L04-U4-LS1-V03","audio_id":"AUD-RW-L04-U4-LS1-V03","tier":"core"},{"word":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","definition":"costing a lot of money","arabic":"غالٍ","example":"Gold rings are expensive.","image_id":"IMG-RW-L04-U4-LS1-V04","audio_id":"AUD-RW-L04-U4-LS1-V04","tier":"core"},{"word":"coin","pos":"noun","ipa":"/kɔɪn/","definition":"a small round piece of metal money","arabic":"عملة معدنية","example":"I have three one-riyal coins.","image_id":"IMG-RW-L04-U4-LS1-V05","audio_id":"AUD-RW-L04-U4-LS1-V05","tier":"core"},{"word":"riyal","pos":"noun","ipa":"/riˈjɑl/","definition":"the money of Saudi Arabia","arabic":"ريال","example":"This book costs 20 riyals.","image_id":"IMG-RW-L04-U4-LS1-V06","audio_id":"AUD-RW-L04-U4-LS1-V06","tier":"core"},{"word":"change","pos":"noun","ipa":"/tʃeɪndʒ/","definition":"the money you get back when you pay more than the price","arabic":"الباقي (من النقود)","example":"I paid 50 riyals and got 10 riyals in change.","image_id":"IMG-RW-L04-U4-LS1-V07","audio_id":"AUD-RW-L04-U4-LS1-V07","tier":"core"},{"word":"customer","pos":"noun","ipa":"/ˈkʌstəmər/","definition":"a person who buys something from a shop","arabic":"زبون","example":"The shop was full of customers.","image_id":"IMG-RW-L04-U4-LS1-V08","audio_id":"AUD-RW-L04-U4-LS1-V08","tier":"core"},{"word":"seller","pos":"noun","ipa":"/ˈsɛlər/","definition":"a person who sells things","arabic":"بائع","example":"The honey seller smiled at us.","image_id":"IMG-RW-L04-U4-LS1-V09","audio_id":"AUD-RW-L04-U4-LS1-V09","tier":"core"},{"word":"spend","pos":"verb","ipa":"/spɛnd/","definition":"to use money to buy things (past: spent)","arabic":"ينفق / يصرف","example":"Don't spend all your money at once.","image_id":"IMG-RW-L04-U4-LS1-V10","audio_id":"AUD-RW-L04-U4-LS1-V10","tier":"core"},{"word":"budget","pos":"noun","ipa":"/ˈbʌdʒɪt/","definition":"a plan for how to spend and save money","arabic":"ميزانية","example":"Our budget for the trip is 200 riyals.","image_id":"IMG-RW-L04-U4-LS1-V11","audio_id":"AUD-RW-L04-U4-LS1-V11","tier":"core"},{"word":"receipt","pos":"noun","ipa":"/rɪˈsit/","definition":"a paper that shows what you bought and paid","arabic":"إيصال","example":"Keep the receipt in your wallet.","image_id":"IMG-RW-L04-U4-LS1-V12","audio_id":"AUD-RW-L04-U4-LS1-V12","tier":"core"},{"word":"wallet","pos":"noun","ipa":"/ˈwɑlɪt/","definition":"a small flat case for money and cards","arabic":"محفظة","example":"Grandpa's wallet is brown.","image_id":"IMG-RW-L04-U4-LS1-V13","audio_id":"AUD-RW-L04-U4-LS1-V13","tier":"core"},{"word":"trade","pos":"verb / noun","ipa":"/treɪd/","definition":"to buy and sell things; to give one thing for another","arabic":"يتاجر / تجارة","example":"Long ago, people traded spices for cloth.","image_id":"IMG-RW-L04-U4-LS1-V14","audio_id":"AUD-RW-L04-U4-LS1-V14","tier":"core"},{"word":"compare","pos":"verb","ipa":"/kəmˈpɛr/","definition":"to look at how two things are the same or different","arabic":"يقارن","example":"Compare the prices before you buy.","image_id":"IMG-RW-L04-U4-LS1-V15","audio_id":"AUD-RW-L04-U4-LS1-V15","tier":"tier2"},{"word":"estimate","pos":"verb","ipa":"/ˈɛstəmeɪt/","definition":"to make a careful guess about a number","arabic":"يقدّر (تقريبيًا)","example":"I estimate that the shopping will cost 80 riyals.","image_id":"IMG-RW-L04-U4-LS1-V16","audio_id":"AUD-RW-L04-U4-LS1-V16","tier":"tier2"},{"word":"afford","pos":"verb","ipa":"/əˈfɔrd/","definition":"to have enough money to buy something","arabic":"يقدر على (ثمن)","example":"We can't afford the 80-riyal honey.","image_id":"IMG-RW-L04-U4-LS1-V17","audio_id":"AUD-RW-L04-U4-LS1-V17","tier":"tier2"}],"explanation":{"text":"Sometimes a sentence gives you the **opposite** (antonym) of a new word. If you know the opposite, you can guess the **meaning** of the new word.\n\nLook for **antonym signal words**: **but, however, not, unlike, instead of, while, although**. They tell you that two ideas are **opposite**.\n\nSteps: (1) Find the **new word**. (2) Find the **signal word**. (3) Find the **word or idea on the other side** – the opposite. (4) Think: the new word means **the opposite of that**. (5) Check that your meaning makes sense in the sentence.","examples":["*The first honey was **expensive**, **but** the second honey was **cheap**.* → expensive = the opposite of cheap = costs a lot.","*Grandpa likes to **save** money, **unlike** Sami, who likes to **spend** it.* → save = the opposite of spend = keep it.","*The seller was **honest**; he was **not** a cheat.* → honest = the opposite of a cheat = tells the truth.","*The old souq is **crowded**, **while** the new mall is almost **empty** in the morning.* → crowded = full of people.","*The plastic toy was **flimsy**. **However**, the wooden one was **strong** and lasted for years.* → flimsy = weak, easy to break.","*Instead of **wasting** our pocket money, we **saved** it in a jar.* → waste = the opposite of save.","*This year, the price of dates **rose**, **although** last year it **fell**.* → rose = went up.","*The customer was **patient**, **not** in a hurry.* → patient = calm and able to wait.","Money opposites: **buy ↔ sell**, **spend ↔ save**, **cheap ↔ expensive**, **customer ↔ seller**."],"common_errors":["✗ This bag is very cheap: it costs 300 riyals! → ✓ This bag is very expensive: it costs 300 riyals! (A big price = **expensive**.)","✗ How much it costs? → ✓ How much does it cost? (Questions need **does**.)","✗ I bought a pen with 5 riyals. → ✓ I bought a pen for 5 riyals. (buy something **for** + price.)","✗ Give me the rest. → ✓ Here is your change. (Money back = **change**.)","✗ The seller sold me. → ✓ The seller sold me a jar of honey. (Say **what** was sold.)","✗ I spended all my money. → ✓ I spent all my money. (Irregular past: **spent**.)","✗ Ignoring the signal word but. → ✓ But shows an opposite – use it! (Signal words are clues.)"],"arabic":"أحيانًا تعطيك الجملة عكس الكلمة الجديدة، فإذا عرفت الضد خمّنت المعنى.\n\nكلمات الإشارة إلى الضد: but, however, not, unlike, instead of, while, although.\n\nالخطوات: جِد الكلمة الجديدة، ثم كلمة الإشارة، ثم الكلمة المقابلة، وفكّر: المعنى هو عكسها، ثم تحقق من المعنى في الجملة.\n\nأضداد المال: buy/sell يشتري/يبيع، spend/save ينفق/يدّخر، cheap/expensive رخيص/غالٍ، customer/seller زبون/بائع."},"video":{"script":[{"time":"00:00–00:20","narration":"Welcome to the old souq! Today, we learn the language of money.","on_screen":"Markets and Money 🪙","visual":"Sami and Grandpa Saleh walk through a busy souq; Saqr the falcon sits on a lantern."},{"time":"00:20–01:10","narration":"Price, cost, cheap, expensive… coins and riyals… a customer, a seller, change and a receipt!","on_screen":"price · cost · cheap · expensive · coin · riyal · change · customer · seller · receipt","visual":"Sami pays a seller, gets change and a receipt."},{"time":"01:10–02:10","narration":"Antonym clues! But, however, not, unlike… If you know the opposite, you know the word!","on_screen":"but · however · not · unlike · instead of","visual":"Two price tags flip: expensive ↔ cheap."},{"time":"02:10–02:40","narration":"Spend or save? Make a budget! Compare prices and estimate the total.","on_screen":"spend · save · budget · compare · estimate · afford","visual":"Sami writes a budget in a notebook."},{"time":"02:40–03:00","narration":"Long ago, people traded at souqs like this. Buying and selling is very old!","on_screen":"trade 🐪","visual":"A camel caravan arrives at an old market."}],"captions_ar":["مرحبًا بكم في السوق القديم! اليوم نتعلم لغة المال.","سعر، تكلفة، رخيص، غالٍ… عملات وريالات… زبون، بائع، الباقي، إيصال!","أدلة الأضداد! but وhowever وnot وunlike… إذا عرفت الضد عرفت الكلمة!","تنفق أم تدّخر؟ ضع ميزانية! قارن الأسعار وقدّر المجموع.","قديمًا كان الناس يتاجرون في أسواق كهذه؛ البيع والشراء قديمان جدًا!"],"voice":"Narrator: American English, cheerful female presenter, speed 0.90. Grandpa Saleh speaks in a warm, slow voice."},"texts":[],"activities":[{"id":"RW-L04-U4-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"A person who buys things from a shop is a ___.","answer":"customer","explanation":"Customer.","explanation_ar":"زبون.","options":["seller","receipt","customer","budget"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The money of Saudi Arabia is the ___.","answer":"riyal","explanation":"Riyal.","explanation_ar":"الريال.","options":["coin","riyal","wallet","trade"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"I paid 20 riyals for a 15-riyal book, so I got 5 riyals in ___.","answer":"change","explanation":"Money back.","explanation_ar":"الباقي.","options":["price","budget","trade","change"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"The paper that shows what you bought and paid is a ___.","answer":"receipt","explanation":"Receipt.","explanation_ar":"إيصال.","options":["receipt","wallet","coin","price"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Grandpa keeps his money and cards in his ___.","answer":"wallet","explanation":"Wallet.","explanation_ar":"محفظة.","options":["wallet","receipt","change","seller"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"*How much does the lantern ___?*","answer":"cost","explanation":"cost.","explanation_ar":"تكلّف.","options":["spend","cost","trade","afford"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L04-U4-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Antonym context clues. Choose.","instructions_ar":"أدلة السياق بالأضداد: اختر.","items":[{"q":"*The first bag was **expensive**, but the second bag was cheap.* *Expensive* means ___.","answer":"costing a lot","explanation":"Opposite of cheap.","explanation_ar":"غالٍ.","options":["costing a little","costing a lot","very small","made of paper"],"dok":1,"skill":"antonym clues","stage":"guided"},{"q":"Which signal word in *Unlike Sami, Grandpa saves his money* shows opposite ideas?","answer":"Unlike","explanation":"Signal word.","explanation_ar":"Unlike.","options":["Unlike","Grandpa","saves","money"],"dok":1,"skill":"signal words","stage":"guided"},{"q":"*The plastic toy was **flimsy**. However, the wooden one was strong.* *Flimsy* means ___.","answer":"weak and easy to break","explanation":"Opposite of strong.","explanation_ar":"ضعيف سهل الكسر.","options":["strong and heavy","expensive","beautiful","weak and easy to break"],"dok":2,"skill":"antonym clues","stage":"guided"},{"q":"*The customer was **patient**, not in a hurry.* *Patient* means ___.","answer":"calm and able to wait","explanation":"Opposite of in a hurry.","explanation_ar":"صبور.","options":["fast and angry","very rich","calm and able to wait","lost"],"dok":2,"skill":"antonym clues","stage":"guided"},{"q":"*The old souq is **crowded**, while the new mall is almost empty in the morning.* *Crowded* means ___.","answer":"full of people","explanation":"Opposite of empty.","explanation_ar":"مزدحم.","options":["very quiet","closed","full of people","very clean"],"dok":2,"skill":"antonym clues","stage":"guided"},{"q":"What is the OPPOSITE of *seller*?","answer":"customer","explanation":"Antonym.","explanation_ar":"زبون.","options":["riyal","price","trader","customer"],"dok":1,"skill":"antonyms","stage":"guided"}]},{"id":"RW-L04-U4-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"Before you buy, ________ the prices at three shops.","answer":"compare","explanation":"Look at the differences.","explanation_ar":"قارن.","stage":"freer"},{"q":"I ________ that our shopping will cost about 80 riyals.","answer":"estimate","explanation":"A careful guess.","explanation_ar":"أقدّر.","stage":"freer"},{"q":"The bike is 900 riyals. We can't ________ it this month.","answer":"afford","explanation":"Enough money.","explanation_ar":"نقدر على ثمنه.","stage":"freer"},{"q":"Our weekly ________ helps us plan how to spend and save.","answer":"budget","explanation":"Money plan.","explanation_ar":"ميزانية.","stage":"freer"},{"q":"Long ago, people ________ spices for cloth at the souq.","answer":"traded","explanation":"Bought, sold or exchanged.","explanation_ar":"تاجروا / قايضوا.","stage":"freer"},{"q":"Don't ________ all your pocket money on sweets!","answer":"spend","explanation":"Use money.","explanation_ar":"تنفق.","stage":"freer"}]},{"id":"RW-L04-U4-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write with the new words.","instructions_ar":"اكتب باستخدام الكلمات الجديدة.","items":[{"q":"Write a sentence with an antonym clue for *expensive*.","answer":"The watch in the window was expensive, but the one in the souq was cheap.","explanation":"Antonym clue.","explanation_ar":"دليل ضد.","dok":2,"skill":"antonym clues","stage":"production"},{"q":"Write two money opposites and use one pair in a sentence.","answer":"spend – save: I spend some of my money and save the rest.","explanation":"Opposites.","explanation_ar":"أضداد.","dok":2,"skill":"antonyms","stage":"production"},{"q":"What is something you would like to buy? Can you afford it now?","answer":"I would like a football. It costs 60 riyals, and I have 40, so I can't afford it yet.","explanation":"afford.","explanation_ar":"afford.","dok":2,"skill":"connect","stage":"production"},{"q":"Why is it a good idea to compare prices?","answer":"Because the same thing can be cheaper in another shop, so you save money.","explanation":"Reason.","explanation_ar":"سبب.","dok":3,"skill":"reasoning","stage":"production"}]}],"game":{"name":"Souq Opposites","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Souq stalls: the child reads a sentence with a new word and an antonym clue; choosing the right meaning earns coins to 'buy' items for a shopping basket. Wrong answers make the seller say, \"Try again, my friend!\"","Set up three 'stalls' with antonym cards face down.","A customer turns over two cards; if they are opposites, he or she keeps them and earns 5 play riyals.","To 'buy' an item, read a clue sentence and say the meaning of the new word.","Pay the price and get the correct change.","The team with the most items in its basket wins."],"data":[]},"exit_quiz":[{"q":"Which word means *not costing much money*?","answer":"cheap","explanation":"Cheap.","explanation_ar":"رخيص.","options":["expensive","budget","cheap","receipt"],"dok":1,"skill":"vocabulary"},{"q":"What is a *budget*?","answer":"a plan for how to spend and save money","explanation":"Budget.","explanation_ar":"ميزانية.","options":["a kind of coin","a shop","a plan for how to spend and save money","a paper bag"],"dok":1,"skill":"vocabulary"},{"q":"Which word is the OPPOSITE of *spend*?","answer":"save","explanation":"Antonym.","explanation_ar":"يدّخر.","options":["save","cost","buy","trade"],"dok":1,"skill":"antonyms"},{"q":"Which signal word often shows an OPPOSITE idea?","answer":"however","explanation":"Signal word.","explanation_ar":"however.","options":["because","first","however","also"],"dok":1,"skill":"signal words"},{"q":"Which question about the price is correct?","answer":"How much does the honey cost?","explanation":"does + base verb.","explanation_ar":"صحيحة.","options":["How much the honey cost?","How much does the honey costs?","How much is cost the honey?","How much does the honey cost?"],"dok":2,"skill":"grammar"},{"q":"*Sami thought the price would **rise**, although last week it fell.* *Rise* means ___.","answer":"go up","explanation":"Opposite of fall.","explanation_ar":"يرتفع.","options":["go down","go up","stay the same","disappear"],"dok":2,"skill":"antonym clues"},{"q":"*We can't **afford** the bike.* This means ___.","answer":"we don't have enough money for it","explanation":"Afford.","explanation_ar":"لا نملك ثمنها.","options":["we don't have enough money for it","we don't like it","it is too small","it is broken"],"dok":2,"skill":"vocabulary"},{"q":"Which sentence about Sami's shopping is correct?","answer":"Sami spent 60 riyals on honey.","explanation":"spent on.","explanation_ar":"صحيحة.","options":["Sami spended 60 riyals on honey.","Sami spend 60 riyals on honey yesterday.","Sami spent 60 riyals with honey.","Sami spent 60 riyals on honey."],"dok":2,"skill":"grammar"},{"q":"*The seller was **genuine**, not fake.* What is the best meaning of *genuine*?","answer":"real and true","explanation":"Opposite of fake.","explanation_ar":"حقيقي.","options":["false","expensive","angry","real and true"],"dok":3,"skill":"antonym clues"},{"q":"A customer has 50 riyals. Which choice shows the BEST use of a budget?","answer":"She buys what is on her list and saves the change.","explanation":"Plan + save.","explanation_ar":"تلتزم بقائمتها وتدّخر الباقي.","options":["She buys the first thing she sees.","She buys what is on her list and saves the change.","She spends it all on sweets.","She borrows more to buy a toy."],"dok":3,"skill":"apply"}],"images":[{"id":"IMG-RW-L04-U4-LS1-V01","prompt":"Picture for the word 'price': a price tag on a box of dates"},{"id":"IMG-RW-L04-U4-LS1-V02","prompt":"Picture for the word 'cost': a lantern with a 30-riyal tag"},{"id":"IMG-RW-L04-U4-LS1-V03","prompt":"Picture for the word 'cheap': a small pen with a 2-riyal tag"},{"id":"IMG-RW-L04-U4-LS1-V04","prompt":"Picture for the word 'expensive': a shiny gold ring with a big price tag"},{"id":"IMG-RW-L04-U4-LS1-V05","prompt":"Picture for the word 'coin': Saudi riyal coins"},{"id":"IMG-RW-L04-U4-LS1-V06","prompt":"Picture for the word 'riyal': a Saudi banknote"},{"id":"IMG-RW-L04-U4-LS1-V07","prompt":"Picture for the word 'change': a seller giving coins back to a customer"},{"id":"IMG-RW-L04-U4-LS1-V08","prompt":"Picture for the word 'customer': people buying at a shop counter"},{"id":"IMG-RW-L04-U4-LS1-V09","prompt":"Picture for the word 'seller': a seller behind a stall"},{"id":"IMG-RW-L04-U4-LS1-V10","prompt":"Picture for the word 'spend': a child paying at a shop"},{"id":"IMG-RW-L04-U4-LS1-V11","prompt":"Picture for the word 'budget': a notebook with a money plan"},{"id":"IMG-RW-L04-U4-LS1-V12","prompt":"Picture for the word 'receipt': a long paper receipt"},{"id":"IMG-RW-L04-U4-LS1-V13","prompt":"Picture for the word 'wallet': a brown leather wallet"},{"id":"IMG-RW-L04-U4-LS1-V14","prompt":"Picture for the word 'trade': an old market with spices and cloth"},{"id":"IMG-RW-L04-U4-LS1-V15","prompt":"Picture for the word 'compare': two price tags side by side"},{"id":"IMG-RW-L04-U4-LS1-V16","prompt":"Picture for the word 'estimate': a child thinking with a calculator and a question mark"},{"id":"IMG-RW-L04-U4-LS1-V17","prompt":"Picture for the word 'afford': an empty wallet next to an expensive item"},{"id":"IMG-RW-L04-U4-LS1-01","prompt":"Sami and Grandpa Saleh shopping at an old souq."},{"id":"IMG-RW-L04-U4-LS1-02","prompt":"Coins, notes, a wallet, a receipt and a price tag."},{"id":"IMG-RW-L04-U4-LS1-03","prompt":"Two honey jars with expensive and cheap price tags."}],"audio":[{"id":"AUD-RW-L04-U4-LS1-V01","script":"price. The price of the dates is 25 riyals."},{"id":"AUD-RW-L04-U4-LS1-V02","script":"cost. How much does this lantern cost?"},{"id":"AUD-RW-L04-U4-LS1-V03","script":"cheap. This pen is cheap – only 2 riyals."},{"id":"AUD-RW-L04-U4-LS1-V04","script":"expensive. Gold rings are expensive."},{"id":"AUD-RW-L04-U4-LS1-V05","script":"coin. I have three one-riyal coins."},{"id":"AUD-RW-L04-U4-LS1-V06","script":"riyal. This book costs 20 riyals."},{"id":"AUD-RW-L04-U4-LS1-V07","script":"change. I paid 50 riyals and got 10 riyals in change."},{"id":"AUD-RW-L04-U4-LS1-V08","script":"customer. The shop was full of customers."},{"id":"AUD-RW-L04-U4-LS1-V09","script":"seller. The honey seller smiled at us."},{"id":"AUD-RW-L04-U4-LS1-V10","script":"spend. Don't spend all your money at once."},{"id":"AUD-RW-L04-U4-LS1-V11","script":"budget. Our budget for the trip is 200 riyals."},{"id":"AUD-RW-L04-U4-LS1-V12","script":"receipt. Keep the receipt in your wallet."},{"id":"AUD-RW-L04-U4-LS1-V13","script":"wallet. Grandpa's wallet is brown."},{"id":"AUD-RW-L04-U4-LS1-V14","script":"trade. Long ago, people traded spices for cloth."},{"id":"AUD-RW-L04-U4-LS1-V15","script":"compare. Compare the prices before you buy."},{"id":"AUD-RW-L04-U4-LS1-V16","script":"estimate. I estimate that the shopping will cost 80 riyals."},{"id":"AUD-RW-L04-U4-LS1-V17","script":"afford. We can't afford the 80-riyal honey."},{"id":"AUD-RW-L04-U4-LS1-VID","script":"Welcome to the old souq! Today, we learn the language of money. Price, cost, cheap, expensive… coins and riyals… a customer, a seller, change and a receipt! Antonym clues! But, however, not, unlike… If you know the opposite, you know the word! Spend or save? Make a budget! Compare prices and estimate the total. Long ago, people traded at souqs like this. Buying and selling is very old!"}]},{"id":"RW-L04-U4-LS2","title":"Trouble at the Souq","lesson_type":"close_reading","objectives":["read a play of about 300 words set in a Saudi souq","use the cast list, scene, speaker names and stage directions to follow a play","explain how stage directions and dialogue show characters' feelings and traits"],"objectives_ar":["قراءة مسرحية من نحو 300 كلمة تدور في سوق سعودي.","استخدام قائمة الشخصيات والمشهد وأسماء المتحدثين والإرشادات المسرحية لمتابعة المسرحية.","شرح كيف تُظهر الإرشادات المسرحية والحوار مشاعر الشخصيات وصفاتها."],"success_criteria":["I can name the parts of a play.","I can use a stage direction to say how a character feels.","I can describe a character with evidence from his lines and actions."],"success_criteria_ar":["أستطيع تسمية أجزاء المسرحية.","أستطيع استخدام الإرشاد المسرحي لقول ما تشعر به الشخصية.","أستطيع وصف شخصية بدليل من أقوالها وأفعالها."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"stall","pos":"noun","ipa":"/stɔl/","definition":"a table or small shop in a market","arabic":"بسطة / دكان صغير","example":"Umm Ali has a spice stall.","image_id":"IMG-RW-L04-U4-LS2-V01","audio_id":"AUD-RW-L04-U4-LS2-V01","tier":"core"},{"word":"cardamom","pos":"noun","ipa":"/ˈkɑrdəməm/","definition":"a spice used in Arabic coffee","arabic":"هيل","example":"Grandpa puts cardamom in his coffee.","image_id":"IMG-RW-L04-U4-LS2-V02","audio_id":"AUD-RW-L04-U4-LS2-V02","tier":"core"},{"word":"in charge","pos":"phrase","ipa":"/ɪn tʃɑrdʒ/","definition":"responsible for making decisions","arabic":"مسؤول","example":"Today, you are in charge of the shopping.","image_id":"IMG-RW-L04-U4-LS2-V03","audio_id":"AUD-RW-L04-U4-LS2-V03","tier":"core"},{"word":"frown","pos":"verb","ipa":"/fraʊn/","definition":"to move your eyebrows down because you are unhappy or worried","arabic":"يعبس","example":"Sami frowned at the high price.","image_id":"IMG-RW-L04-U4-LS2-V04","audio_id":"AUD-RW-L04-U4-LS2-V04","tier":"core"},{"word":"lane","pos":"noun","ipa":"/leɪn/","definition":"a narrow street","arabic":"زقاق / ممر","example":"Abu Fahd called from across the lane.","image_id":"IMG-RW-L04-U4-LS2-V05","audio_id":"AUD-RW-L04-U4-LS2-V05","tier":"core"},{"word":"panic","pos":"verb","ipa":"/ˈpænɪk/","definition":"to feel sudden fear and not think clearly","arabic":"يذعر","example":"Sami panicked when the wallet was gone.","image_id":"IMG-RW-L04-U4-LS2-V06","audio_id":"AUD-RW-L04-U4-LS2-V06","tier":"core"},{"word":"relieved","pos":"adjective","ipa":"/rɪˈlivd/","definition":"happy because a worry has gone","arabic":"مرتاح (بعد قلق)","example":"Sami was relieved to see his wallet.","image_id":"IMG-RW-L04-U4-LS2-V07","audio_id":"AUD-RW-L04-U4-LS2-V07","tier":"core"}],"explanation":{"text":"A **play** is a story written to be **acted**. It has a **cast list** (the characters), a **scene** (where and when), **speaker names** before each line and **stage directions** in *(italics and brackets)*.\n\n**Stage directions** are not spoken aloud. They tell the actors **what to do** and **how to feel**: *(panicking)*, *(calmly)*, *(counting the notes carefully)*. They are great clues to a character's **feelings**.\n\nTo understand a character, look at **what he says** (his lines) and **what he does** (stage directions). Then choose a **trait word** (careful, calm, honest, clever) and give **evidence**.","examples":["**Cast list:** *Narrator, Sami, Grandpa Saleh, Umm Ali, Abu Fahd* – who is in the play.","**Scene:** *The old souq on a busy Saturday morning.* – the setting.","**Narrator:** tells the audience what happens between the lines: *First, they stopped at Umm Ali's spice stall.*","**Stage direction → feeling:** *SAMI: (panicking) Grandpa! The wallet is gone!* → Sami is scared.","**Stage direction → feeling:** *SAMI: (relieved) Thank you so much!* → his worry is gone.","**Trait – careful:** *(counting the notes carefully)* and *That leaves 65 riyals for the honey.*","**Trait – calm and wise:** *GRANDPA: (calmly) Shouting won't find it. Let's go back the way we came.*","**Trait – honest:** *ABU FAHD: … I knew you would come back.* – he kept the wallet safe.","Reading aloud: say only the **lines**, not the speaker names or the stage directions; **act** the directions."],"common_errors":["✗ Reading the stage directions aloud as lines. → ✓ Act them; don't say them. (Directions are for actors.)","✗ Saying 'Sami is happy' with no evidence. → ✓ Sami is relieved: '(relieved) Thank you so much!' (Always give evidence.)","✗ Thinking the narrator is a character in the souq. → ✓ The narrator tells the story to the audience. (Narrator = storyteller.)","✗ Grandpa say, 'Spend carefully.' → ✓ Grandpa says, 'Spend carefully.' (One person → **says**.)","✗ Sami was relief. → ✓ Sami was relieved. (Adjective: **relieved**.)","✗ The honey is cost 80 riyals. → ✓ The honey costs 80 riyals. (**costs** (no is).)"],"arabic":"المسرحية قصة مكتوبة لتُمثَّل، وفيها قائمة الشخصيات والمشهد وأسماء المتحدثين قبل كل سطر والإرشادات المسرحية بين قوسين.\n\nالإرشادات المسرحية لا تُقال بصوت عالٍ، بل تخبر الممثلين بما يفعلونه وبما يشعرون به، وهي أدلة مهمة على مشاعر الشخصيات.\n\nلفهم الشخصية انظر إلى ما تقوله وما تفعله، ثم اختر صفة (حريص، هادئ، أمين، ذكي) وقدّم الدليل.\n\nالراوي يحكي للجمهور ما يحدث بين الأسطر، وليس شخصية في السوق."},"video":{"script":[{"time":"00:00–00:20","narration":"The curtain opens… Welcome to the old souq! Today, a wallet goes missing.","on_screen":"Trouble at the Souq 🎭","visual":"A red curtain opens on a busy souq."},{"time":"00:20–01:50","narration":"Grandpa Saleh handed Sami a shopping list and a small brown wallet…","on_screen":"(play)","visual":"The play is acted with stage directions appearing in brackets beside each actor."},{"time":"01:50–02:25","narration":"Stage directions tell actors how to feel: panicking, calmly, relieved!","on_screen":"(panicking) · (calmly) · (relieved)","visual":"Sami's face changes with each stage direction."},{"time":"02:25–02:45","narration":"What do the lines and actions show? Careful Sami, calm Grandpa, honest Abu Fahd!","on_screen":"careful · calm · honest","visual":"Trait labels appear above each character."},{"time":"02:45–03:00","narration":"An honest seller is worth more than gold!","on_screen":"The End 👏","visual":"The curtain closes; the audience claps."}],"captions_ar":["يُرفع الستار… مرحبًا بكم في السوق القديم! اليوم تضيع محفظة.","أعطى الجد صالح سامي قائمة تسوق ومحفظة بنية صغيرة…","الإرشادات المسرحية تخبر الممثلين بما يشعرون به: مذعور، بهدوء، مرتاح!","ماذا تُظهر الأقوال والأفعال؟ سامي الحريص، والجد الهادئ، وأبو فهد الأمين!","البائع الأمين أغلى من الذهب!"],"voice":"Narrator: American English, theatrical male voice, speed 0.90. Different voices for Sami, Grandpa, Umm Ali and Abu Fahd."},"texts":[{"type":"reading","title":"Trouble at the Souq","body":"**Characters:** Narrator, Sami, Grandpa Saleh, Umm Ali (a spice seller), Abu Fahd (a honey seller)\n\n**Scene:** The old souq on a busy Saturday morning.\n\n**NARRATOR:** Grandpa Saleh handed Sami a shopping list and a small brown wallet with 100 riyals inside.\n\n**GRANDPA:** Today, you are in charge. We need dates, cardamom and honey. Our budget is 100 riyals, so spend carefully.\n\n**NARRATOR:** First, they stopped at Umm Ali's spice stall.\n\n**UMM ALI:** *(weighing the dates)* One kilo of dates is 25 riyals, and the cardamom is 10.\n\n**SAMI:** *(counting the notes carefully)* Here you are. That leaves 65 riyals for the honey.\n\n**NARRATOR:** At the next stall, Sami read a sign and frowned.\n\n**SAMI:** Grandpa, this honey costs 80 riyals! It's too expensive. We can't afford it.\n\n**GRANDPA:** *(smiling)* So, what can we do?\n\n**SAMI:** *(thinking hard)* We can compare prices at other stalls!\n\n**ABU FAHD:** *(calling from across the lane)* Fresh mountain honey! Only 60 riyals!\n\n**SAMI:** That's much cheaper. One jar, please. *(He pays, puts the receipt and the change in the wallet and walks away happily.)*\n\n**NARRATOR:** A few minutes later, Sami reached into his pocket. It was empty.\n\n**SAMI:** *(panicking)* Grandpa! The wallet is gone!\n\n**GRANDPA:** *(calmly)* Shouting won't find it. Let's go back the way we came, step by step.\n\n**NARRATOR:** They walked back slowly, looking at the ground. When they reached the honey stall, Abu Fahd was holding up something small and brown.\n\n**ABU FAHD:** Is this yours, young man? It fell next to my jars. I saw my shop's receipt inside, so I knew you would come back.\n\n**SAMI:** *(relieved)* Thank you so much! Our five riyals are still inside!\n\n**GRANDPA:** *(putting a hand on Sami's shoulder)* Today you learned three things: compare prices, keep your wallet safe, and remember that an honest seller is worth more than gold.","word_count":306,"audio_id":"AUD-RW-L04-U4-LS2-T1","id":"TXT-RW-L04-U4-LS2-1","genre":"drama","role":"main","difficulty":"450L–600L","glossary":[{"word":"stall","definition":"a table or small shop in a market","arabic":"بسطة / دكان صغير"},{"word":"cardamom","definition":"a spice used in Arabic coffee","arabic":"هيل"},{"word":"lane","definition":"a narrow street","arabic":"زقاق / ممر"}]}],"activities":[{"id":"RW-L04-U4-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the play. Choose the answer.","instructions_ar":"اقرأ المسرحية واختر الإجابة.","items":[{"q":"Where does *Trouble at the Souq* take place?","answer":"at the old souq on a Saturday morning","explanation":"Scene.","explanation_ar":"في السوق القديم صباح السبت.","options":["at the old souq on a Saturday morning","at a school on Monday","at a beach at night","in a big mall"],"dok":1,"skill":"setting","stage":"controlled"},{"q":"What was the shopping budget?","answer":"100 riyals","explanation":"Grandpa's line.","explanation_ar":"100 ريال.","options":["65 riyals","100 riyals","60 riyals","80 riyals"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How much did the dates and the cardamom cost together?","answer":"35 riyals","explanation":"25 + 10.","explanation_ar":"35 ريالًا.","options":["25 riyals","10 riyals","35 riyals","60 riyals"],"dok":2,"skill":"key details","stage":"controlled"},{"q":"Why couldn't they buy the first honey?","answer":"It cost 80 riyals, but they had only 65.","explanation":"too expensive.","explanation_ar":"كان غاليًا.","options":["It cost 80 riyals, but they had only 65.","It was not fresh.","The seller was rude.","Grandpa didn't like honey."],"dok":2,"skill":"cause and effect","stage":"controlled"},{"q":"Where did the wallet fall?","answer":"next to Abu Fahd's honey jars","explanation":"Abu Fahd's line.","explanation_ar":"بجانب جرار العسل.","options":["at Umm Ali's stall","at home","in the car","next to Abu Fahd's honey jars"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How did Abu Fahd know the wallet was Sami's?","answer":"He saw his shop's receipt inside.","explanation":"Abu Fahd's line.","explanation_ar":"رأى إيصال متجره.","options":["Sami's name was on it.","He saw his shop's receipt inside.","Grandpa told him.","Umm Ali told him."],"dok":2,"skill":"key details","stage":"controlled"}]},{"id":"RW-L04-U4-LS2-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Parts of a play and characters. Choose.","instructions_ar":"أجزاء المسرحية والشخصيات: اختر.","items":[{"q":"What is the *cast list*?","answer":"the list of characters in the play","explanation":"Cast.","explanation_ar":"قائمة الشخصيات.","options":["the price list","the list of characters in the play","the shopping list","the last line"],"dok":1,"skill":"parts of a play","stage":"guided"},{"q":"What does the stage direction *(panicking)* tell the actor playing Sami?","answer":"to show sudden fear","explanation":"Stage direction.","explanation_ar":"أن يُظهر الذعر.","options":["to laugh","to sit down","to show sudden fear","to sing"],"dok":1,"skill":"stage directions","stage":"guided"},{"q":"Which word BEST describes Sami at Umm Ali's stall?","answer":"careful","explanation":"(counting the notes carefully)","explanation_ar":"حريص.","options":["careful","lazy","rude","greedy"],"dok":2,"skill":"character traits","stage":"guided"},{"q":"Which line shows that Grandpa is calm and wise?","answer":"Shouting won't find it. Let's go back the way we came, step by step.","explanation":"Calm advice.","explanation_ar":"سطر الجد الهادئ.","options":["Fresh mountain honey! Only 60 riyals!","Grandpa! The wallet is gone!","Shouting won't find it. Let's go back the way we came, step by step.","One kilo of dates is 25 riyals."],"dok":2,"skill":"evidence","stage":"guided"},{"q":"What trait does Abu Fahd show?","answer":"honesty","explanation":"He returned the wallet.","explanation_ar":"الأمانة.","options":["laziness","honesty","anger","shyness"],"dok":2,"skill":"character traits","stage":"guided"},{"q":"Why does Grandpa let Sami be *in charge* of the shopping?","answer":"to help Sami learn to handle money","explanation":"Inference.","explanation_ar":"ليتعلم سامي التعامل مع المال.","options":["because Grandpa is tired of shopping","because Sami asked for a toy","because Umm Ali told him to","to help Sami learn to handle money"],"dok":3,"skill":"inference","stage":"guided"}]},{"id":"RW-L04-U4-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Find the evidence.","instructions_ar":"ابحث عن الدليل.","items":[{"q":"Underline the stage direction that shows Sami was thinking of a solution.","answer":"(thinking hard)","explanation":"Thinking.","explanation_ar":"يفكر بجدية.","evidence":"(thinking hard)","text_id":"TXT-RW-L04-U4-LS2-1","dok":1,"skill":"stage directions","stage":"freer","sentences":["**Characters:** Narrator, Sami, Grandpa Saleh, Umm Ali (a spice seller), Abu Fahd (a honey seller)","**Scene:** The old souq on a busy Saturday morning.","**NARRATOR:** Grandpa Saleh handed Sami a shopping list and a small brown wallet with 100 riyals inside.","**GRANDPA:** Today, you are in charge.","We need dates, cardamom and honey.","Our budget is 100 riyals, so spend carefully.","**NARRATOR:** First, they stopped at Umm Ali's spice stall.","**UMM ALI:** *(weighing the dates)* One kilo of dates is 25 riyals, and the cardamom is 10.","**SAMI:** *(counting the notes carefully)* Here you are.","That leaves 65 riyals for the honey.","**NARRATOR:** At the next stall, Sami read a sign and frowned.","**SAMI:** Grandpa, this honey costs 80 riyals!","It's too expensive.","We can't afford it.","**GRANDPA:** *(smiling)* So, what can we do?","**SAMI:** *(thinking hard)* We can compare prices at other stalls!","**ABU FAHD:** *(calling from across the lane)* Fresh mountain honey!","Only 60 riyals!","**SAMI:** That's much cheaper.","One jar, please. *(He pays, puts the receipt and the change in the wallet and walks away happily.)*","**NARRATOR:** A few minutes later, Sami reached into his pocket.","It was empty.","**SAMI:** *(panicking)* Grandpa!","The wallet is gone!","**GRANDPA:** *(calmly)* Shouting won't find it.","Let's go back the way we came, step by step.","**NARRATOR:** They walked back slowly, looking at the ground.","When they reached the honey stall, Abu Fahd was holding up something small and brown.","**ABU FAHD:** Is this yours, young man?","It fell next to my jars.","I saw my shop's receipt inside, so I knew you would come back.","**SAMI:** *(relieved)* Thank you so much!","Our five riyals are still inside!","**GRANDPA:** *(putting a hand on Sami's shoulder)* Today you learned three things: compare prices, keep your wallet safe, and remember that an honest seller is worth more than gold."]},{"q":"Underline the line that shows Sami can do money math.","answer":"That leaves 65 riyals for the honey.","explanation":"100 – 35 = 65.","explanation_ar":"يحسب الباقي.","evidence":"That leaves 65 riyals for the honey.","text_id":"TXT-RW-L04-U4-LS2-1","dok":2,"skill":"evidence","stage":"freer","sentences":["**Characters:** Narrator, Sami, Grandpa Saleh, Umm Ali (a spice seller), Abu Fahd (a honey seller)","**Scene:** The old souq on a busy Saturday morning.","**NARRATOR:** Grandpa Saleh handed Sami a shopping list and a small brown wallet with 100 riyals inside.","**GRANDPA:** Today, you are in charge.","We need dates, cardamom and honey.","Our budget is 100 riyals, so spend carefully.","**NARRATOR:** First, they stopped at Umm Ali's spice stall.","**UMM ALI:** *(weighing the dates)* One kilo of dates is 25 riyals, and the cardamom is 10.","**SAMI:** *(counting the notes carefully)* Here you are.","That leaves 65 riyals for the honey.","**NARRATOR:** At the next stall, Sami read a sign and frowned.","**SAMI:** Grandpa, this honey costs 80 riyals!","It's too expensive.","We can't afford it.","**GRANDPA:** *(smiling)* So, what can we do?","**SAMI:** *(thinking hard)* We can compare prices at other stalls!","**ABU FAHD:** *(calling from across the lane)* Fresh mountain honey!","Only 60 riyals!","**SAMI:** That's much cheaper.","One jar, please. *(He pays, puts the receipt and the change in the wallet and walks away happily.)*","**NARRATOR:** A few minutes later, Sami reached into his pocket.","It was empty.","**SAMI:** *(panicking)* Grandpa!","The wallet is gone!","**GRANDPA:** *(calmly)* Shouting won't find it.","Let's go back the way we came, step by step.","**NARRATOR:** They walked back slowly, looking at the ground.","When they reached the honey stall, Abu Fahd was holding up something small and brown.","**ABU FAHD:** Is this yours, young man?","It fell next to my jars.","I saw my shop's receipt inside, so I knew you would come back.","**SAMI:** *(relieved)* Thank you so much!","Our five riyals are still inside!","**GRANDPA:** *(putting a hand on Sami's shoulder)* Today you learned three things: compare prices, keep your wallet safe, and remember that an honest seller is worth more than gold."]},{"q":"What does *an honest seller is worth more than gold* mean?","answer":"Honest people are more valuable than money.","explanation":"Figurative language.","explanation_ar":"الأمانة أثمن من المال.","options":["Abu Fahd sells gold.","Honey is made of gold.","Gold is cheap.","Honest people are more valuable than money."],"dok":3,"skill":"figurative language","stage":"freer"},{"q":"What is the job of the NARRATOR in this play?","answer":"to tell the audience what happens between the lines","explanation":"Narrator.","explanation_ar":"يحكي ما يحدث بين الأسطر.","options":["to tell the audience what happens between the lines","to sell honey","to lose the wallet","to count the money"],"dok":2,"skill":"parts of a play","stage":"freer"}]},{"id":"RW-L04-U4-LS2-A4","type":"open","stage":"production","instructions":"Writing: Explain and act.","instructions_ar":"اشرح ومثّل.","items":[{"q":"How did Sami feel when he found the wallet was gone, and how did he feel at the end? Give evidence.","answer":"At first he panicked: '(panicking) Grandpa! The wallet is gone!' At the end he was relieved: '(relieved) Thank you so much!'","explanation":"Change in feelings.","explanation_ar":"تغيّر المشاعر.","dok":2,"skill":"character feelings","stage":"production"},{"q":"Describe Grandpa Saleh with one trait word and evidence.","answer":"Grandpa is calm. He says, '(calmly) Shouting won't find it.'","explanation":"Trait + evidence.","explanation_ar":"صفة + دليل.","dok":2,"skill":"character traits","stage":"production"},{"q":"Write a new stage direction for Abu Fahd when he sees Sami coming back.","answer":"(waving the wallet with a big smile)","explanation":"Stage direction.","explanation_ar":"إرشاد مسرحي.","dok":2,"skill":"writing a play","stage":"production"},{"q":"What would YOU do if you found a wallet in the souq? Why?","answer":"I would give it to the owner or to a guard, because it is not mine and someone is worried.","explanation":"Opinion + reason.","explanation_ar":"رأي + سبب.","dok":3,"skill":"connect","stage":"production"}]},{"id":"RW-L04-U4-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Trouble at the Souq\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Trouble at the Souq”.","answer":"306 words","title":"Trouble at the Souq","body":"**Characters:** Narrator, Sami, Grandpa Saleh, Umm Ali (a spice seller), Abu Fahd (a honey seller)\n\n**Scene:** The old souq on a busy Saturday morning.\n\n**NARRATOR:** Grandpa Saleh handed Sami a shopping list and a small brown wallet with 100 riyals inside.\n\n**GRANDPA:** Today, you are in charge. We need dates, cardamom and honey. Our budget is 100 riyals, so spend carefully.\n\n**NARRATOR:** First, they stopped at Umm Ali's spice stall.\n\n**UMM ALI:** *(weighing the dates)* One kilo of dates is 25 riyals, and the cardamom is 10.\n\n**SAMI:** *(counting the notes carefully)* Here you are. That leaves 65 riyals for the honey.\n\n**NARRATOR:** At the next stall, Sami read a sign and frowned.\n\n**SAMI:** Grandpa, this honey costs 80 riyals! It's too expensive. We can't afford it.\n\n**GRANDPA:** *(smiling)* So, what can we do?\n\n**SAMI:** *(thinking hard)* We can compare prices at other stalls!\n\n**ABU FAHD:** *(calling from across the lane)* Fresh mountain honey! Only 60 riyals!\n\n**SAMI:** That's much cheaper. One jar, please. *(He pays, puts the receipt and the change in the wallet and walks away happily.)*\n\n**NARRATOR:** A few minutes later, Sami reached into his pocket. It was empty.\n\n**SAMI:** *(panicking)* Grandpa! The wallet is gone!\n\n**GRANDPA:** *(calmly)* Shouting won't find it. Let's go back the way we came, step by step.\n\n**NARRATOR:** They walked back slowly, looking at the ground. When they reached the honey stall, Abu Fahd was holding up something small and brown.\n\n**ABU FAHD:** Is this yours, young man? It fell next to my jars. I saw my shop's receipt inside, so I knew you would come back.\n\n**SAMI:** *(relieved)* Thank you so much! Our five riyals are still inside!\n\n**GRANDPA:** *(putting a hand on Sami's shoulder)* Today you learned three things: compare prices, keep your wallet safe, and remember that an honest seller is worth more than gold.","words":306,"limit":231}],"time_limit_sec":231}],"game":{"name":"Stage Direction Charades","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Act it out: a character avatar shows a feeling; the child chooses the matching stage direction and then the line it belongs to. Correct matches make the audience clap; the curtain closes when all matches are found.","A player takes a stage-direction card and acts it with no words.","The team guesses the stage direction.","Then the team finds the line from the play that goes with it.","One point for the direction, one point for the matching line.","The team with the most points takes a bow!"],"data":[]},"exit_quiz":[{"q":"Who are the two sellers in the play?","answer":"Umm Ali and Abu Fahd","explanation":"Cast list.","explanation_ar":"أم علي وأبو فهد.","options":["Sami and Grandpa","Umm Ali and Abu Fahd","the Narrator and Sami","Grandpa and Umm Ali"],"dok":1,"skill":"characters"},{"q":"What is a *stall*?","answer":"a table or small shop in a market","explanation":"Glossary.","explanation_ar":"بسطة.","options":["a kind of honey","a wallet","a narrow street","a table or small shop in a market"],"dok":1,"skill":"vocabulary"},{"q":"*Sami **frowned** at the price.* *Frowned* shows that he was ___.","answer":"unhappy or worried","explanation":"Frown.","explanation_ar":"منزعج أو قلق.","options":["very happy","sleepy","hungry","unhappy or worried"],"dok":1,"skill":"vocabulary in context"},{"q":"Which part of a play tells actors HOW to act?","answer":"stage directions","explanation":"Directions.","explanation_ar":"الإرشادات المسرحية.","options":["stage directions","the title","the cast list","speaker names"],"dok":1,"skill":"parts of a play"},{"q":"Which sentence about the honey is correct?","answer":"The honey costs 60 riyals.","explanation":"costs.","explanation_ar":"صحيحة.","options":["The honey is cost 60 riyals.","The honey cost 60 riyals now.","The honey costs 60 riyals.","The honey costing 60 riyals."],"dok":2,"skill":"grammar"},{"q":"How much money was left in the wallet at the end?","answer":"5 riyals","explanation":"100 – 35 – 60.","explanation_ar":"5 ريالات.","options":["35 riyals","5 riyals","65 riyals","0 riyals"],"dok":2,"skill":"math in text"},{"q":"What does the stage direction *(relieved)* show?","answer":"Sami's worry has gone.","explanation":"Relieved.","explanation_ar":"زال قلقه.","options":["Sami is angry.","Sami's worry has gone.","Sami is tired.","Sami wants more honey."],"dok":2,"skill":"stage directions"},{"q":"What was Sami's SOLUTION when the first honey was too expensive?","answer":"He compared prices at other stalls.","explanation":"Problem → solution.","explanation_ar":"قارن الأسعار.","options":["He asked Umm Ali for money.","He went home.","He compared prices at other stalls.","He bought a smaller jar of dates."],"dok":2,"skill":"problem and solution"},{"q":"What is the BEST lesson of *Trouble at the Souq*?","answer":"Being careful and honest with money matters.","explanation":"Theme.","explanation_ar":"الحرص والأمانة في المال.","options":["Being careful and honest with money matters.","Honey is always expensive.","Wallets are brown.","Souqs are busy."],"dok":3,"skill":"theme"},{"q":"Why does the playwright use a narrator?","answer":"to move the story from place to place and explain what happens between lines","explanation":"Author's craft.","explanation_ar":"لنقل القصة وشرح ما بين الأسطر.","options":["to sell things to the audience","to make the play longer","to move the story from place to place and explain what happens between lines","to replace the stage directions"],"dok":3,"skill":"author's craft"}],"images":[{"id":"IMG-RW-L04-U4-LS2-V01","prompt":"Picture for the word 'stall': a market stall with spices"},{"id":"IMG-RW-L04-U4-LS2-V02","prompt":"Picture for the word 'cardamom': green cardamom pods"},{"id":"IMG-RW-L04-U4-LS2-V03","prompt":"Picture for the word 'in charge': a boy holding a shopping list proudly"},{"id":"IMG-RW-L04-U4-LS2-V04","prompt":"Picture for the word 'frown': a boy frowning"},{"id":"IMG-RW-L04-U4-LS2-V05","prompt":"Picture for the word 'lane': a narrow lane in an old market"},{"id":"IMG-RW-L04-U4-LS2-V06","prompt":"Picture for the word 'panic': a boy with wide eyes holding empty pockets"},{"id":"IMG-RW-L04-U4-LS2-V07","prompt":"Picture for the word 'relieved': a boy sighing and smiling"},{"id":"IMG-RW-L04-U4-LS2-01","prompt":"Sami comparing honey prices at two stalls."},{"id":"IMG-RW-L04-U4-LS2-02","prompt":"A honey seller returning Sami's wallet."},{"id":"IMG-RW-L04-U4-LS2-03","prompt":"A labelled play script."}],"audio":[{"id":"AUD-RW-L04-U4-LS2-V01","script":"stall. Umm Ali has a spice stall."},{"id":"AUD-RW-L04-U4-LS2-V02","script":"cardamom. Grandpa puts cardamom in his coffee."},{"id":"AUD-RW-L04-U4-LS2-V03","script":"in charge. Today, you are in charge of the shopping."},{"id":"AUD-RW-L04-U4-LS2-V04","script":"frown. Sami frowned at the high price."},{"id":"AUD-RW-L04-U4-LS2-V05","script":"lane. Abu Fahd called from across the lane."},{"id":"AUD-RW-L04-U4-LS2-V06","script":"panic. Sami panicked when the wallet was gone."},{"id":"AUD-RW-L04-U4-LS2-V07","script":"relieved. Sami was relieved to see his wallet."},{"id":"AUD-RW-L04-U4-LS2-T1","script":"**Characters:** Narrator, Sami, Grandpa Saleh, Umm Ali (a spice seller), Abu Fahd (a honey seller) **Scene:** The old souq on a busy Saturday morning. **NARRATOR:** Grandpa Saleh handed Sami a shopping list and a small brown wallet with 100 riyals inside. **GRANDPA:** Today, you are in charge. We need dates, cardamom and honey. Our budget is 100 riyals, so spend carefully. **NARRATOR:** First, they stopped at Umm Ali's spice stall. **UMM ALI:** *(weighing the dates)* One kilo of dates is 25 riyals, and the cardamom is 10. **SAMI:** *(counting the notes carefully)* Here you are. That leaves 65 riyals for the honey. **NARRATOR:** At the next stall, Sami read a sign and frowned. **SAMI:** Grandpa, this honey costs 80 riyals! It's too expensive. We can't afford it. **GRANDPA:** *(smiling)* So, what can we do? **SAMI:** *(thinking hard)* We can compare prices at other stalls! **ABU FAHD:** *(calling from across the lane)* Fresh mountain honey! Only 60 riyals! **SAMI:** That's much cheaper. One jar, please. *(He pays, puts the receipt and the change in the wallet and walks away happily.)* **NARRATOR:** A few minutes later, Sami reached into his pocket. It was empty. **SAMI:** *(panicking)* Grandpa! The wallet is gone! **GRANDPA:** *(calmly)* Shouting won't find it. Let's go back the way we came, step by step. **NARRATOR:** They walked back slowly, looking at the ground. When they reached the honey stall, Abu Fahd was holding up something small and brown. **ABU FAHD:** Is this yours, young man? It fell next to my jars. I saw my shop's receipt inside, so I knew you would come back. **SAMI:** *(relieved)* Thank you so much! Our five riyals are still inside! **GRANDPA:** *(putting a hand on Sami's shoulder)* Today you learned three things: compare prices, keep your wallet safe, and remember that an honest seller is worth more than gold."},{"id":"AUD-RW-L04-U4-LS2-VID","script":"The curtain opens… Welcome to the old souq! Today, a wallet goes missing. Grandpa Saleh handed Sami a shopping list and a small brown wallet… Stage directions tell actors how to feel: panicking, calmly, relieved! What do the lines and actions show? Careful Sami, calm Grandpa, honest Abu Fahd! An honest seller is worth more than gold!"}]},{"id":"RW-L04-U4-LS3","title":"Problem and solution: \"How to Make a Pocket-Money Budget\"","lesson_type":"strategy_paired_text","objectives":["find problems and solutions in a play and in a how-to text","use signal words (problem, solve, solution, so, if … then, to fix this) to find them","complete a Problem–Solution Chart and judge whether each solution worked"],"objectives_ar":["إيجاد المشكلات والحلول في مسرحية ونص إرشادي.","استخدام كلمات الإشارة لإيجادها.","إكمال جدول المشكلة والحل والحكم على نجاح كل حل."],"success_criteria":["I can say what the problem is and who has it.","I can find the solution and the steps that solve the problem.","I can explain the result: did the solution work?"],"success_criteria_ar":["أستطيع قول ما المشكلة ومن يواجهها.","أستطيع إيجاد الحل والخطوات التي تحل المشكلة.","أستطيع شرح النتيجة: هل نجح الحل؟"],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"pocket money","pos":"noun","ipa":"/ˈpɑkɪt ˌmʌni/","definition":"money that parents give children to spend or save","arabic":"مصروف الجيب","example":"I get 20 riyals of pocket money every week.","image_id":"IMG-RW-L04-U4-LS3-V01","audio_id":"AUD-RW-L04-U4-LS3-V01","tier":"core"},{"word":"save","pos":"verb","ipa":"/seɪv/","definition":"to keep money so you can use it later","arabic":"يدّخر","example":"I save 10 riyals every week.","image_id":"IMG-RW-L04-U4-LS3-V02","audio_id":"AUD-RW-L04-U4-LS3-V02","tier":"core"},{"word":"envelope","pos":"noun","ipa":"/ˈɛnvəloʊp/","definition":"a paper cover for letters or money","arabic":"ظرف","example":"Put the money in the SAVE envelope.","image_id":"IMG-RW-L04-U4-LS3-V03","audio_id":"AUD-RW-L04-U4-LS3-V03","tier":"core"},{"word":"jar","pos":"noun","ipa":"/dʒɑr/","definition":"a glass container with a wide top","arabic":"برطمان / مرطبان","example":"My SAVE jar is almost full.","image_id":"IMG-RW-L04-U4-LS3-V04","audio_id":"AUD-RW-L04-U4-LS3-V04","tier":"core"},{"word":"solve","pos":"verb","ipa":"/sɑlv/","definition":"to find an answer to a problem","arabic":"يحلّ","example":"A budget can solve this problem.","image_id":"IMG-RW-L04-U4-LS3-V05","audio_id":"AUD-RW-L04-U4-LS3-V05","tier":"core"},{"word":"solution","pos":"noun","ipa":"/səˈluʃən/","definition":"a way to fix a problem","arabic":"حلّ","example":"Comparing prices was a good solution.","image_id":"IMG-RW-L04-U4-LS3-V06","audio_id":"AUD-RW-L04-U4-LS3-V06","tier":"core"},{"word":"reach","pos":"verb","ipa":"/ritʃ/","definition":"to get to a place or a goal","arabic":"يصل إلى / يبلغ","example":"You will reach your goal in six weeks.","image_id":"IMG-RW-L04-U4-LS3-V07","audio_id":"AUD-RW-L04-U4-LS3-V07","tier":"core"}],"explanation":{"text":"Many texts are built around a **problem** (something wrong) and a **solution** (a way to fix it). Ask: **What is the problem? Who has it? What is the solution? Did it work (the result)?**\n\n**Signal words:** problem, trouble, worry, need; **solve, solution, fix, answer, to fix this, so, as a result, if … then**.\n\nIn a **story or play**, a **character** has the problem and tries to solve it. In a **how-to text**, the writer gives the **reader** a problem in the introduction and the **steps** are the solution.","examples":["Play – Problem 1: *This honey costs 80 riyals! … We can't afford it.*","Play – Solution 1: *We can compare prices at other stalls!* → Result: they buy honey for 60 riyals.","Play – Problem 2: *Grandpa! The wallet is gone!*","Play – Solution 2: *Let's go back the way we came, step by step.* → Result: Abu Fahd returns the wallet.","How-to – Problem: *Do you spend all your pocket money in two days and then have nothing left?*","How-to – Solution: *A budget can solve this problem.* + seven steps.","How-to – a step that solves part of the problem: *Put the saving money in the SAVE jar first, before you spend anything.*","Signal words: ***solve***, ***If*** *you save 10 riyals a week,* ***you will*** *reach your goal.*","Tip as a solution: *If you want something expensive, wait one day before you buy it.* → It stops you from buying things you don't need."],"common_errors":["✗ The problem is honey. → ✓ The problem is that the honey is too expensive. (Say what is **wrong**.)","✗ Forgetting the result. → ✓ Say whether the solution worked. (Problem → solution → result.)","✗ Mixing up problem and solution. → ✓ Ask: Is it something wrong or a way to fix it? (Check each part.)","✗ The solution is that Sami lost the wallet. → ✓ The problem is that Sami lost the wallet. (Something wrong = a **problem**.)","✗ If you will save, you reach your goal. → ✓ If you save, you will reach your goal. (If + present → will.)","✗ I don't have no money. → ✓ I don't have any money. (Use **any** after **don't**.)"],"arabic":"كثير من النصوص مبنية على مشكلة (شيء خاطئ) وحل (طريقة لإصلاحه). اسأل: ما المشكلة؟ من يواجهها؟ ما الحل؟ هل نجح؟\n\nكلمات الإشارة: problem, trouble, solve, solution, fix, so, as a result, if … then.\n\nفي القصة أو المسرحية تواجه الشخصية المشكلة وتحاول حلها، وفي النص الإرشادي يعرض الكاتب مشكلة القارئ في المقدمة وتكون الخطوات هي الحل.\n\nلا تنسَ النتيجة: هل نجح الحل أم لا؟"},"video":{"script":[{"time":"00:00–00:20","narration":"Uh-oh! Your pocket money is gone in two days. What's the problem? What's the solution?","on_screen":"Problem → Solution 💡","visual":"A boy holds an empty wallet on Monday; a calendar shows five more days."},{"time":"00:20–01:20","narration":"How to Make a Pocket-Money Budget…","on_screen":"(how-to text)","visual":"Noura demonstrates each step with a notebook and two jars labelled SAVE and SPEND."},{"time":"01:20–02:00","narration":"In the play, Sami had two problems: expensive honey and a lost wallet!","on_screen":"Problem 1 · Problem 2","visual":"Two problem cards flip to show their solutions."},{"time":"02:00–02:40","narration":"Ask: What's the problem? Who has it? What's the solution? Did it work?","on_screen":"Problem–Solution Chart","visual":"A chart fills in row by row."},{"time":"02:40–03:00","narration":"Six weeks later… GOAL! The new football!","on_screen":"Result ⚽","visual":"The SAVE jar is full and a boy buys a football."}],"captions_ar":["أوه! نفد مصروفك في يومين. ما المشكلة؟ وما الحل؟","كيف تضع ميزانية لمصروف الجيب…","في المسرحية واجه سامي مشكلتين: عسل غالٍ ومحفظة ضائعة!","اسأل: ما المشكلة؟ من يواجهها؟ ما الحل؟ هل نجح؟","بعد ستة أسابيع… هدف! الكرة الجديدة!"],"voice":"Narrator: American English, friendly male teacher, speed 0.90. Noura reads the how-to text."},"texts":[{"type":"reading","title":"How to Make a Pocket-Money Budget","body":"Do you spend all your pocket money in two days and then have nothing left? A budget can solve this problem. A budget is a simple plan for your money.\n\n**You need:** a notebook, a pencil and two jars or envelopes labelled SAVE and SPEND.\n\n**1.** Write down how much pocket money you get every week – for example, 20 riyals.\n\n**2.** Choose a goal to save for, such as a new football that costs 60 riyals.\n\n**3.** Decide how much to save each week. If you save 10 riyals a week, you will reach your goal in six weeks.\n\n**4.** Put the saving money in the SAVE jar first, before you spend anything.\n\n**5.** Put the rest in the SPEND jar. This is the money you can use for snacks or small things.\n\n**6.** Every time you buy something, write it down and keep the receipt.\n\n**7.** At the end of the week, check your notebook. Did you stay inside your budget?\n\n**Tip:** If you want something expensive, wait one day before you buy it. You may find that you don't really need it!","word_count":184,"audio_id":"AUD-RW-L04-U4-LS3-T1","id":"TXT-RW-L04-U4-LS3-1","genre":"procedural","role":"paired","difficulty":"450L–600L","glossary":[{"word":"pocket money","definition":"money that parents give children to spend or save","arabic":"مصروف الجيب"},{"word":"goal","definition":"something you want and work for","arabic":"هدف"},{"word":"label","definition":"to write a name on something","arabic":"يُعنون / يكتب اسمًا على"}]}],"activities":[{"id":"RW-L04-U4-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *How to Make a Pocket-Money Budget*. Choose the answer.","instructions_ar":"اقرأ النص واختر الإجابة.","items":[{"q":"What problem does the introduction describe?","answer":"spending all your pocket money in two days","explanation":"Introduction.","explanation_ar":"إنفاق المصروف كله في يومين.","options":["spending all your pocket money in two days","losing your wallet in the souq","buying expensive honey","forgetting your notebook"],"dok":1,"skill":"problem","text_id":"TXT-RW-L04-U4-LS3-1","stage":"controlled"},{"q":"What do you need to make the budget?","answer":"a notebook, a pencil and two jars or envelopes","explanation":"You need.","explanation_ar":"دفتر وقلم وبرطمانان.","options":["a calculator and a bank card","a phone and a computer","honey and dates","a notebook, a pencil and two jars or envelopes"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"In the example, how much does the new football cost?","answer":"60 riyals","explanation":"Step 2.","explanation_ar":"60 ريالًا.","options":["20 riyals","10 riyals","60 riyals","6 riyals"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Which jar do you fill FIRST?","answer":"the SAVE jar","explanation":"Step 4.","explanation_ar":"برطمان الادخار.","options":["the SPEND jar","both at the end of the week","neither","the SAVE jar"],"dok":1,"skill":"sequence","stage":"controlled"},{"q":"What should you do every time you buy something?","answer":"write it down and keep the receipt","explanation":"Step 6.","explanation_ar":"اكتبه واحتفظ بالإيصال.","options":["throw away the receipt","write it down and keep the receipt","buy something else","empty the SAVE jar"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What does the tip tell you to do before buying something expensive?","answer":"wait one day","explanation":"Tip.","explanation_ar":"انتظر يومًا.","options":["wait one day","buy it quickly","ask a seller","use the SAVE jar"],"dok":2,"skill":"key details","stage":"controlled"}]},{"id":"RW-L04-U4-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Problem and solution. Choose.","instructions_ar":"المشكلة والحل: اختر.","items":[{"q":"Which signal word in the introduction tells you a SOLUTION is coming?","answer":"solve","explanation":"*A budget can solve this problem.*","explanation_ar":"solve.","options":["nothing","solve","days","left"],"dok":1,"skill":"signal words","stage":"guided"},{"q":"In the play, what is Sami's SECOND problem?","answer":"The wallet is gone.","explanation":"Problem 2.","explanation_ar":"ضياع المحفظة.","options":["The wallet is gone.","The honey is too expensive.","Umm Ali has no dates.","Grandpa is tired."],"dok":1,"skill":"problem","stage":"guided"},{"q":"What solution does Grandpa suggest for the lost wallet?","answer":"go back the way they came, step by step","explanation":"Grandpa's line.","explanation_ar":"العودة خطوة بخطوة.","options":["buy a new wallet","go back the way they came, step by step","shout for help","go home and forget it"],"dok":2,"skill":"solution","stage":"guided"},{"q":"If you save 10 riyals a week, how long will it take to save for the 60-riyal football?","answer":"six weeks","explanation":"Step 3.","explanation_ar":"ستة أسابيع.","options":["two weeks","ten weeks","one week","six weeks"],"dok":2,"skill":"result","stage":"guided"},{"q":"Why does step 4 tell you to fill the SAVE jar FIRST?","answer":"so you don't spend the saving money by mistake","explanation":"Purpose of the step.","explanation_ar":"حتى لا تنفق مال الادخار.","options":["because the SAVE jar is bigger","because receipts go in it","so you don't spend the saving money by mistake","so the SPEND jar stays empty"],"dok":3,"skill":"author's purpose","stage":"guided"},{"q":"How are the problems in the play and in the how-to text ALIKE?","answer":"Both are about using money carefully.","explanation":"Compare.","explanation_ar":"كلاهما عن استخدام المال بحرص.","options":["Both are about lost wallets.","Both happen in a souq.","Both are about honey.","Both are about using money carefully."],"dok":3,"skill":"compare texts","stage":"guided"}]},{"id":"RW-L04-U4-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Problem–Solution Chart.","instructions_ar":"أكمل جدول المشكلة والحل.","items":[{"q":"Problem – What is wrong in the play (the honey) and in the how-to text?","answer":"Play: the honey costs 80 riyals, but they only have 65. How-to: you spend all your pocket money in two days.","explanation":"Problems.","explanation_ar":"المشكلتان.","dok":1,"skill":"problem","stage":"freer"},{"q":"Who has each problem?","answer":"Play: Sami and Grandpa. How-to: the reader – a child with pocket money.","explanation":"Who.","explanation_ar":"مَن.","dok":1,"skill":"problem","stage":"freer"},{"q":"Solution – What do they do?","answer":"Play: Sami compares prices at other stalls. How-to: you make a budget with SAVE and SPEND jars.","explanation":"Solutions.","explanation_ar":"الحلول.","dok":2,"skill":"solution","stage":"freer"},{"q":"Result – Did each solution work? How do you know?","answer":"Yes. They buy honey for 60 riyals, and the reader can save enough for the football in six weeks.","explanation":"Results.","explanation_ar":"النتائج.","dok":2,"skill":"result","stage":"freer"}]},{"id":"RW-L04-U4-LS3-A4","type":"open","stage":"production","instructions":"Writing: Solve and explain.","instructions_ar":"حلّ واشرح.","items":[{"q":"Faris wants a 90-riyal game. He gets 15 riyals a week and saves 10. How many weeks will he need?","answer":"He will need nine weeks, because 9 × 10 = 90.","explanation":"Math + budget.","explanation_ar":"حساب + ميزانية.","dok":2,"skill":"apply","stage":"production"},{"q":"Write another solution for Sami's lost wallet.","answer":"He could ask the sellers at each stall if they had found a brown wallet.","explanation":"New solution.","explanation_ar":"حل جديد.","dok":2,"skill":"solution","stage":"production"},{"q":"Write a money problem you have had and your solution.","answer":"I always lost my coins at school, so I started to keep them in a small purse in my bag.","explanation":"Problem + solution.","explanation_ar":"مشكلة + حل.","dok":2,"skill":"connect","stage":"production"},{"q":"Which solution in the two texts do you think is the BEST? Why?","answer":"Saving first in the SAVE jar, because it helps you reach your goal without thinking about it every day.","explanation":"Evaluate.","explanation_ar":"قيّم.","dok":3,"skill":"evaluate","stage":"production"}]},{"id":"RW-L04-U4-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"How to Make a Pocket-Money Budget\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “How to Make a Pocket-Money Budget”.","answer":"184 words","title":"How to Make a Pocket-Money Budget","body":"Do you spend all your pocket money in two days and then have nothing left? A budget can solve this problem. A budget is a simple plan for your money.\n\n**You need:** a notebook, a pencil and two jars or envelopes labelled SAVE and SPEND.\n\n**1.** Write down how much pocket money you get every week – for example, 20 riyals.\n\n**2.** Choose a goal to save for, such as a new football that costs 60 riyals.\n\n**3.** Decide how much to save each week. If you save 10 riyals a week, you will reach your goal in six weeks.\n\n**4.** Put the saving money in the SAVE jar first, before you spend anything.\n\n**5.** Put the rest in the SPEND jar. This is the money you can use for snacks or small things.\n\n**6.** Every time you buy something, write it down and keep the receipt.\n\n**7.** At the end of the week, check your notebook. Did you stay inside your budget?\n\n**Tip:** If you want something expensive, wait one day before you buy it. You may find that you don't really need it!","words":184,"limit":144}],"time_limit_sec":144},{"id":"RW-L04-U4-LS3-ORG","type":"organizer","organizer":"Problem–Solution Chart","instructions":"Organizer: Fill in the chart for the play (one problem) and for the how-to text.","items":[{"q":"Problem – What is wrong?","answer":"Play: the honey costs 80 riyals, but only 65 are left · How-to: you spend all your pocket money in two days"},{"q":"Who has the problem?","answer":"Play: Sami and Grandpa · How-to: the reader (a child with pocket money)"},{"q":"Solution – What do they do?","answer":"Play: compare prices at other stalls · How-to: make a budget with SAVE and SPEND jars (7 steps)"},{"q":"Result – Did it work?","answer":"Play: yes – they buy honey for 60 riyals · How-to: yes – you save 10 riyals a week and reach your goal in six weeks"}]}],"game":{"name":"Problem Solvers' Market","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Market of solutions: a customer at a stall shows a money problem; the child chooses the best solution from three stalls and sees the result. Good solutions fill a SAVE jar; poor ones empty it.","Teams get a pile of problem cards.","They find the best solution card for each problem.","They say the likely result.","The other teams vote: 'Good solution' or 'Try again'.","Each good match earns 10 play riyals; the richest team wins."],"data":[]},"exit_quiz":[{"q":"What is a *solution*?","answer":"a way to fix a problem","explanation":"Solution.","explanation_ar":"حلّ.","options":["a way to fix a problem","a kind of jar","a price","a seller"],"dok":1,"skill":"vocabulary"},{"q":"In a how-to text, where do you usually find the PROBLEM?","answer":"in the introduction","explanation":"Structure.","explanation_ar":"في المقدمة.","options":["in the last step","in the You need list","in the introduction","in the glossary"],"dok":1,"skill":"text structure"},{"q":"*You will **reach** your goal in six weeks.* *Reach* means ___.","answer":"get to","explanation":"Reach.","explanation_ar":"تصل إلى.","options":["lose","get to","forget","spend"],"dok":1,"skill":"vocabulary in context"},{"q":"Which signal word often shows a solution?","answer":"fix","explanation":"Solution signal.","explanation_ar":"fix.","options":["fix","trouble","worry","problem"],"dok":1,"skill":"signal words"},{"q":"Which sentence about Faris's money is correct?","answer":"Faris doesn't have any money left.","explanation":"doesn't have any.","explanation_ar":"صحيحة.","options":["Faris doesn't have no money left.","Faris don't have any money left.","Faris doesn't has any money left.","Faris doesn't have any money left."],"dok":2,"skill":"grammar"},{"q":"What was the RESULT of comparing prices in the play?","answer":"They bought honey for 60 riyals.","explanation":"Result.","explanation_ar":"اشتروا عسلًا بستين ريالًا.","options":["They lost the wallet.","They bought honey for 60 riyals.","They bought nothing.","They paid 80 riyals."],"dok":2,"skill":"result"},{"q":"Which step in the budget text helps you know where your money went?","answer":"Write it down and keep the receipt.","explanation":"Step 6.","explanation_ar":"اكتبه واحتفظ بالإيصال.","options":["Choose a goal.","Put the rest in the SPEND jar.","Wait one day.","Write it down and keep the receipt."],"dok":2,"skill":"solution"},{"q":"Why does the writer start with a question about spending money in two days?","answer":"to show the reader the problem the steps will solve","explanation":"Hook + problem.","explanation_ar":"ليعرض المشكلة.","options":["to tell a funny story","to list the materials","to show the reader the problem the steps will solve","to give the last step"],"dok":2,"skill":"author's purpose"},{"q":"Sami saves 5 riyals a week for a 40-riyal book. What is the BEST new solution to reach his goal faster?","answer":"save 10 riyals a week instead of 5","explanation":"Apply.","explanation_ar":"يدّخر 10 ريالات أسبوعيًا.","options":["save 10 riyals a week instead of 5","spend more on snacks","stop writing down what he buys","throw away his receipts"],"dok":3,"skill":"apply"},{"q":"Which is TRUE about problems and solutions in BOTH texts?","answer":"Thinking carefully before you act helps you solve money problems.","explanation":"Synthesis.","explanation_ar":"التفكير قبل التصرف يحل المشكلات.","options":["Only adults can solve money problems.","Money problems cannot be solved.","Thinking carefully before you act helps you solve money problems.","Shouting is a good solution."],"dok":3,"skill":"compare texts"}],"images":[{"id":"IMG-RW-L04-U4-LS3-V01","prompt":"Picture for the word 'pocket money': a parent giving coins to a child"},{"id":"IMG-RW-L04-U4-LS3-V02","prompt":"Picture for the word 'save': coins going into a jar labelled SAVE"},{"id":"IMG-RW-L04-U4-LS3-V03","prompt":"Picture for the word 'envelope': two envelopes labelled SAVE and SPEND"},{"id":"IMG-RW-L04-U4-LS3-V04","prompt":"Picture for the word 'jar': a glass jar with coins"},{"id":"IMG-RW-L04-U4-LS3-V05","prompt":"Picture for the word 'solve': a child putting the last puzzle piece in place"},{"id":"IMG-RW-L04-U4-LS3-V06","prompt":"Picture for the word 'solution': a light bulb over a child's head"},{"id":"IMG-RW-L04-U4-LS3-V07","prompt":"Picture for the word 'reach': a child reaching a finish flag"},{"id":"IMG-RW-L04-U4-LS3-01","prompt":"A child sharing coins between SAVE and SPEND jars."},{"id":"IMG-RW-L04-U4-LS3-02","prompt":"A budget notebook with receipts."},{"id":"IMG-RW-L04-U4-LS3-03","prompt":"A problem and solution chart."}],"audio":[{"id":"AUD-RW-L04-U4-LS3-V01","script":"pocket money. I get 20 riyals of pocket money every week."},{"id":"AUD-RW-L04-U4-LS3-V02","script":"save. I save 10 riyals every week."},{"id":"AUD-RW-L04-U4-LS3-V03","script":"envelope. Put the money in the SAVE envelope."},{"id":"AUD-RW-L04-U4-LS3-V04","script":"jar. My SAVE jar is almost full."},{"id":"AUD-RW-L04-U4-LS3-V05","script":"solve. A budget can solve this problem."},{"id":"AUD-RW-L04-U4-LS3-V06","script":"solution. Comparing prices was a good solution."},{"id":"AUD-RW-L04-U4-LS3-V07","script":"reach. You will reach your goal in six weeks."},{"id":"AUD-RW-L04-U4-LS3-T1","script":"Do you spend all your pocket money in two days and then have nothing left? A budget can solve this problem. A budget is a simple plan for your money. **You need:** a notebook, a pencil and two jars or envelopes labelled SAVE and SPEND. **1.** Write down how much pocket money you get every week – for example, 20 riyals. **2.** Choose a goal to save for, such as a new football that costs 60 riyals. **3.** Decide how much to save each week. If you save 10 riyals a week, you will reach your goal in six weeks. **4.** Put the saving money in the SAVE jar first, before you spend anything. **5.** Put the rest in the SPEND jar. This is the money you can use for snacks or small things. **6.** Every time you buy something, write it down and keep the receipt. **7.** At the end of the week, check your notebook. Did you stay inside your budget? **Tip:** If you want something expensive, wait one day before you buy it. You may find that you don't really need it!"},{"id":"AUD-RW-L04-U4-LS3-VID","script":"Uh-oh! Your pocket money is gone in two days. What's the problem? What's the solution? How to Make a Pocket-Money Budget… In the play, Sami had two problems: expensive honey and a lost wallet! Ask: What's the problem? Who has it? What's the solution? Did it work? Six weeks later… GOAL! The new football!"}]},{"id":"RW-L04-U4-LS4","title":"Writing Skill: Clear numbered steps","lesson_type":"writing_skill","objectives":["write clear numbered steps with imperative (bossy) verbs","put one action in each step and add exact details (how much, where, how)","organize a how-to text: title, introduction, You need list, steps and a tip"],"objectives_ar":["كتابة خطوات مرقّمة واضحة بأفعال الأمر.","وضع فعل واحد في كل خطوة وإضافة تفاصيل دقيقة.","تنظيم النص الإرشادي: عنوان ومقدمة وقائمة أدوات وخطوات ونصيحة."],"success_criteria":["I can start each step with an imperative verb.","I can write one clear action with exact details in each step.","I can put the steps in the correct order."],"success_criteria_ar":["أستطيع بدء كل خطوة بفعل أمر.","أستطيع كتابة فعل واحد واضح بتفاصيل دقيقة في كل خطوة.","أستطيع ترتيب الخطوات ترتيبًا صحيحًا."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"subtract","pos":"verb","ipa":"/səbˈtrækt/","definition":"to take one number away from another","arabic":"يطرح","example":"Subtract 35 from 50.","image_id":"IMG-RW-L04-U4-LS4-V01","audio_id":"AUD-RW-L04-U4-LS4-V01","tier":"core"},{"word":"total","pos":"noun","ipa":"/ˈtoʊtəl/","definition":"the whole amount after adding everything","arabic":"المجموع","example":"The total is 35 riyals.","image_id":"IMG-RW-L04-U4-LS4-V02","audio_id":"AUD-RW-L04-U4-LS4-V02","tier":"core"},{"word":"note","pos":"noun","ipa":"/noʊt/","definition":"a piece of paper money","arabic":"ورقة نقدية","example":"He paid with a 50-riyal note.","image_id":"IMG-RW-L04-U4-LS4-V03","audio_id":"AUD-RW-L04-U4-LS4-V03","tier":"core"},{"word":"counter","pos":"noun","ipa":"/ˈkaʊntər/","definition":"the long table in a shop where you pay","arabic":"منضدة الدفع","example":"Check your change at the counter.","image_id":"IMG-RW-L04-U4-LS4-V04","audio_id":"AUD-RW-L04-U4-LS4-V04","tier":"core"},{"word":"politely","pos":"adverb","ipa":"/pəˈlaɪtli/","definition":"in a kind and respectful way","arabic":"بأدب","example":"Politely show the seller the receipt.","image_id":"IMG-RW-L04-U4-LS4-V05","audio_id":"AUD-RW-L04-U4-LS4-V05","tier":"core"},{"word":"imperative","pos":"noun / adjective","ipa":"/ɪmˈpɛrətɪv/","definition":"a verb form that tells someone to do something (Read! Count!)","arabic":"صيغة الأمر","example":"Each step starts with an imperative verb.","image_id":"IMG-RW-L04-U4-LS4-V06","audio_id":"AUD-RW-L04-U4-LS4-V06","tier":"core"},{"word":"mistake","pos":"noun","ipa":"/mɪˈsteɪk/","definition":"something that is not correct","arabic":"خطأ","example":"Anyone can make a mistake.","image_id":"IMG-RW-L04-U4-LS4-V07","audio_id":"AUD-RW-L04-U4-LS4-V07","tier":"core"}],"explanation":{"text":"Good instructions are **easy to follow**. A reader should be able to do each step **without asking a question**.\n\nRules: (1) **Number** the steps in the **right order**. (2) **Start with an imperative (bossy) verb**: *Read, Count, Put, Write*. (3) Write **one action** in each step. (4) Add **exact details**: how much, how many, where, how. (5) Add a **tip** or a **warning** if it helps.\n\nYou can start a step with a **time phrase** or an **if-clause** before the verb: *Before you pay, read the price.* / *If they are different, show the receipt.* Don't use *you must*, *you should* or *-ing* at the start of every step.","examples":["Vague: *Do the money.* → Clear: ***Count the change, starting with the biggest note.***","Two actions: *Pay and count and leave.* → Split: ***4. Count the change. 5. Compare it with your answer.***","Exact detail: ***Subtract the price from the money you gave: 50 – 35 = 15 riyals.***","Where: ***Put the change and the receipt in your wallet.***","When: ***Before you pay, read the total price.***","Condition: ***If the change is wrong, politely show the seller the receipt.***","Imperative verbs for money: **save, spend, count, add, subtract, compare, write, keep, choose, pay**.","Not imperative: *You are counting the money.* → ***Count the money.***","Tip: ***Always check your change at the counter.*** / Warning: ***Never leave your wallet on the counter.***"],"common_errors":["✗ You must to count the change. → ✓ Count the change. (Use the verb alone.)","✗ Counting the change. → ✓ Count the change. (Imperatives have no **-ing**.)","✗ Pay, count, compare and leave. → ✓ One action per step. (Split long steps.)","✗ Put the money somewhere. → ✓ Put the money in your wallet. (Give **exact** details.)","✗ Steps in the wrong order (count before paying). → ✓ Pay first, then count the change. (Check the order.)","✗ Don't to forget the receipt. → ✓ Don't forget the receipt. (**Don't** + verb.)","✗ Subtract 35 to 50. → ✓ Subtract 35 from 50. (subtract **from**.)"],"arabic":"التعليمات الجيدة سهلة الاتباع؛ يستطيع القارئ تنفيذ كل خطوة دون أن يسأل.\n\nالقواعد: رقّم الخطوات بالترتيب الصحيح، وابدأ بفعل أمر، واكتب فعلًا واحدًا في كل خطوة، وأضف تفاصيل دقيقة (كم؟ أين؟ كيف؟)، وأضف نصيحة أو تحذيرًا.\n\nيمكن أن تبدأ الخطوة بعبارة زمنية أو بـ if ثم فعل الأمر، ولا تستخدم you must أو صيغة -ing في بداية كل خطوة.\n\nانتبه: subtract from (اطرح من)، وDon't + الفعل دون to."},"video":{"script":[{"time":"00:00–00:20","narration":"Did you get the right change? Omar shows you how to check – in seven clear steps!","on_screen":"How to Check Your Change 🧾","visual":"Omar stands at a shop counter with a 50-riyal note."},{"time":"00:20–01:20","narration":"1. Before you pay, read the total price…","on_screen":"(Omar's steps)","visual":"Each step is acted out: reading the receipt, paying, subtracting, counting, comparing."},{"time":"01:20–02:00","narration":"Start with a bossy verb: Read! Count! Compare! Put!","on_screen":"Imperative verbs 📣","visual":"Verbs jump to the front of each step."},{"time":"02:00–02:40","narration":"One action per step, with exact details: how much, where, how.","on_screen":"Clear vs. vague","visual":"A vague step 'Do the money' turns into a clear one."},{"time":"02:40–03:00","narration":"Always check your change at the counter!","on_screen":"Tip 💡","visual":"Omar puts the change and the receipt into his wallet and smiles."}],"captions_ar":["هل أخذت الباقي الصحيح؟ عمر يعلّمك كيف تتحقق في سبع خطوات واضحة!","1. قبل أن تدفع، اقرأ السعر الإجمالي…","ابدأ بفعل أمر: اقرأ! عُدّ! قارن! ضع!","فعل واحد في كل خطوة مع تفاصيل دقيقة: كم؟ أين؟ كيف؟","تحقّق دائمًا من الباقي عند منضدة الدفع!"],"voice":"Narrator: American English, clear male teacher, speed 0.90. Omar demonstrates at a shop counter."},"texts":[{"type":"model","title":"How to Check Your Change (by Omar)","body":"Sellers are usually honest, but anyone can make a mistake. Checking your change takes only a few seconds, and it keeps your budget safe.\n\n**You need:** your money, the receipt and a little math.\n\n**1.** Before you pay, read the total price on the receipt or on the screen.\n\n**2.** Look carefully at how much money you give the seller.\n\n**3.** Subtract the price from the money you gave. For example, 50 – 35 = 15 riyals.\n\n**4.** Count the change the seller gives you, starting with the biggest note.\n\n**5.** Compare your answer with the change in your hand. If they are the same, say \"Thank you!\"\n\n**6.** If they are different, politely show the seller the receipt and your math.\n\n**7.** Put the change and the receipt in your wallet before you walk away.\n\n**Tip:** Always check your change at the counter. It is much harder to fix a mistake later at home!","word_count":153,"audio_id":"AUD-RW-L04-U4-LS4-T1","id":"TXT-RW-L04-U4-LS4-1","genre":"model text","role":"model","difficulty":"450L–600L","glossary":[],"annotations":["**Title:** starts with **How to…** and tells the goal.","**Introduction:** says **why** the steps are useful (the problem they solve).","**You need:** a short list before the steps.","**Numbers:** the steps are in the **correct order**, 1 to 7.","**Bossy (imperative) verbs:** each step **starts with a verb** – *Read, Look, Subtract, Count, Compare, Put*. Steps 1 and 6 start with a time or condition (*Before you pay, If they are different*) and then the verb.","**One action per step** and **exact details:** *starting with the biggest note*, *50 – 35 = 15 riyals*.","**Tip:** extra advice at the end."]}],"activities":[{"id":"RW-L04-U4-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read Omar's steps. Choose the best answer.","instructions_ar":"اقرأ خطوات عمر واختر أفضل إجابة.","items":[{"q":"Why should you check your change, according to Omar?","answer":"Anyone can make a mistake.","explanation":"Introduction.","explanation_ar":"لأن أي شخص قد يخطئ.","options":["Sellers are never honest.","Receipts are always wrong.","It is fun to count.","Anyone can make a mistake."],"dok":1,"skill":"purpose","stage":"controlled"},{"q":"What do you do BEFORE you pay?","answer":"read the total price","explanation":"Step 1.","explanation_ar":"تقرأ السعر الإجمالي.","options":["count the change","read the total price","put the receipt in your wallet","show the seller your math"],"dok":1,"skill":"sequence","stage":"controlled"},{"q":"In Omar's example, how much change should you get from 50 riyals for a 35-riyal total?","answer":"15 riyals","explanation":"50 – 35.","explanation_ar":"15 ريالًا.","options":["15 riyals","35 riyals","50 riyals","85 riyals"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How should you count the change?","answer":"starting with the biggest note","explanation":"Step 4.","explanation_ar":"بدءًا بالورقة الأكبر.","options":["starting with the smallest coin","without looking","starting with the biggest note","at home later"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What should you do if the change is wrong?","answer":"politely show the seller the receipt and your math","explanation":"Step 6.","explanation_ar":"تُري البائع الإيصال بأدب.","options":["shout at the seller","walk away","politely show the seller the receipt and your math","throw away the receipt"],"dok":2,"skill":"key details","stage":"controlled"},{"q":"Why does Omar's tip say to check your change at the counter?","answer":"It is much harder to fix a mistake later at home.","explanation":"Tip.","explanation_ar":"لأن تصحيح الخطأ لاحقًا أصعب.","options":["It is much harder to fix a mistake later at home.","The counter is clean.","Sellers like it.","Wallets are heavy."],"dok":2,"skill":"cause and effect","stage":"controlled"}]},{"id":"RW-L04-U4-LS4-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Clear steps. Choose.","instructions_ar":"الخطوات الواضحة: اختر.","items":[{"q":"Which step for saving pocket money starts with an imperative verb?","answer":"Write your weekly pocket money in your notebook.","explanation":"Bossy verb first.","explanation_ar":"يبدأ بفعل أمر.","options":["You are writing your money.","Writing your money in a notebook.","Write your weekly pocket money in your notebook.","Your money is in a notebook."],"dok":1,"skill":"imperatives","stage":"guided"},{"q":"Which step about the SAVE jar is CLEAREST?","answer":"Put 10 riyals in the SAVE jar every Sunday.","explanation":"Exact details.","explanation_ar":"الأوضح.","options":["Put some money somewhere.","Put 10 riyals in the SAVE jar every Sunday.","Do the jar.","Money, jar, Sunday."],"dok":2,"skill":"details","stage":"guided"},{"q":"Which step about paying needs to be SPLIT into two steps?","answer":"Pay the seller, count the change and walk home.","explanation":"One action per step.","explanation_ar":"تحتاج إلى تقسيم.","options":["Count the change.","Pay the seller, count the change and walk home.","Pay the seller.","Read the total."],"dok":2,"skill":"one action per step","stage":"guided"},{"q":"Which step about the change is written correctly?","answer":"Don't forget your change.","explanation":"Don't + verb.","explanation_ar":"صحيحة.","options":["Don't forget your change.","Don't to forget your change.","Not forget your change.","You must to not forget your change."],"dok":2,"skill":"grammar","stage":"guided"},{"q":"Which order of steps for buying dates makes sense?","answer":"Read the price. → Pay the seller. → Count your change. → Put the change in your wallet.","explanation":"Logical order.","explanation_ar":"الترتيب المنطقي.","options":["Count your change. → Read the price. → Pay the seller.","Put the change in your wallet. → Pay the seller. → Read the price.","Pay the seller. → Read the price. → Count your change.","Read the price. → Pay the seller. → Count your change. → Put the change in your wallet."],"dok":2,"skill":"sequence","stage":"guided"},{"q":"Which sentence about Omar's math uses *subtract* correctly?","answer":"Subtract 35 from 50 to find the change.","explanation":"subtract from.","explanation_ar":"صحيحة.","options":["Subtract 35 to 50 to find the change.","Subtract from 35 50 to find the change.","Subtracting 35 at 50 to find the change.","Subtract 35 from 50 to find the change."],"dok":3,"skill":"grammar","stage":"guided"}]},{"id":"RW-L04-U4-LS4-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Complete the steps with the verb bank.","instructions_ar":"أكمل الخطوات من بنك الأفعال.","items":[{"q":"1. ________ a goal, such as a 60-riyal football.","answer":"Choose","explanation":"Bossy verb.","explanation_ar":"اختر.","stage":"freer"},{"q":"2. ________ how much you get every week in your notebook.","answer":"Write","explanation":"Bossy verb.","explanation_ar":"اكتب.","stage":"freer"},{"q":"3. ________ the prices at three shops before you buy.","answer":"Compare","explanation":"Bossy verb.","explanation_ar":"قارن.","stage":"freer"},{"q":"4. ________ the total of your shopping list before you go.","answer":"Add","explanation":"Bossy verb.","explanation_ar":"اجمع.","stage":"freer"},{"q":"5. ________ the receipt in your wallet.","answer":"Keep","explanation":"Bossy verb.","explanation_ar":"احتفظ بـ.","stage":"freer"},{"q":"6. ________ only the money on your list.","answer":"Spend","explanation":"Bossy verb.","explanation_ar":"أنفق.","stage":"freer"}]},{"id":"RW-L04-U4-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write and fix steps.","instructions_ar":"اكتب الخطوات وصحّحها.","items":[{"q":"Fix this vague step: *Do the coins.*","answer":"Count the coins and write the total in your notebook.","explanation":"Clear + detail.","explanation_ar":"واضحة + تفصيل.","dok":1,"skill":"editing","stage":"production"},{"q":"Split this long step into two steps: *Pay the seller and put the change in your wallet.*","answer":"1. Pay the seller. 2. Put the change in your wallet.","explanation":"One action each.","explanation_ar":"فعل واحد لكل خطوة.","dok":2,"skill":"editing","stage":"production"},{"q":"Write three clear steps for *How to Count Coins*.","answer":"1. Sort the coins into groups of the same value. 2. Count each group. 3. Add the groups to find the total.","explanation":"Three steps.","explanation_ar":"ثلاث خطوات.","dok":2,"skill":"writing steps","stage":"production"},{"q":"Write one tip or warning for shopping at a busy souq.","answer":"Tip: Keep your wallet in a front pocket so it doesn't fall out.","explanation":"Tip.","explanation_ar":"نصيحة.","dok":2,"skill":"writing steps","stage":"production"}]}],"game":{"name":"Robot Shopper","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Robot shopper: the child drags step cards into order and chooses clear imperative verbs; the robot follows the steps exactly. Vague or wrong steps make the robot do something silly (like pay with a banana!).","One student wears the robot headband and can only do EXACTLY what the steps say.","The team writes numbered steps for buying one item.","The team reads the steps; the robot acts them out.","If the robot gets stuck, the team must fix the step.","Points: robot buys the item = 3; correct change = 2; no fixes needed = 2 bonus."],"data":[]},"exit_quiz":[{"q":"What is an *imperative* verb?","answer":"a verb that tells someone to do something","explanation":"Imperative.","explanation_ar":"فعل الأمر.","options":["a verb in the past","a describing word","a verb that tells someone to do something","a number"],"dok":1,"skill":"imperatives"},{"q":"Which part of a how-to text lists the things you will use?","answer":"You need","explanation":"Structure.","explanation_ar":"قائمة الأدوات.","options":["the tip","You need","the last step","the title only"],"dok":1,"skill":"text structure"},{"q":"*The **total** is 35 riyals.* *Total* means ___.","answer":"the whole amount","explanation":"Total.","explanation_ar":"المجموع.","options":["the whole amount","the change","the seller","the wallet"],"dok":1,"skill":"vocabulary"},{"q":"Which step starts correctly?","answer":"Count the change carefully.","explanation":"Imperative.","explanation_ar":"صحيحة.","options":["You counting the change carefully.","Counted the change carefully.","The change carefully count.","Count the change carefully."],"dok":1,"skill":"imperatives"},{"q":"Which step gives EXACT details?","answer":"Put 5 riyals in the SAVE jar every Friday.","explanation":"Details.","explanation_ar":"تفاصيل دقيقة.","options":["Put some money in a jar.","Put 5 riyals in the SAVE jar every Friday.","Save money.","Do the saving."],"dok":2,"skill":"details"},{"q":"Which step about the wallet is written correctly?","answer":"Don't leave your wallet on the counter.","explanation":"Don't + verb.","explanation_ar":"صحيحة.","options":["Don't leave your wallet on the counter.","Don't to leave your wallet on the counter.","No leave your wallet on the counter.","Not leaving your wallet on the counter."],"dok":2,"skill":"grammar"},{"q":"Why should each step have only ONE action?","answer":"so the reader can follow it easily without missing anything","explanation":"Clarity.","explanation_ar":"ليسهل اتباعها.","options":["so the text is longer","so there are no numbers","so the reader can follow it easily without missing anything","so the title is shorter"],"dok":2,"skill":"one action per step"},{"q":"Which step should come LAST when buying something?","answer":"Put the change and the receipt in your wallet.","explanation":"Order.","explanation_ar":"الخطوة الأخيرة.","options":["Read the price.","Give the money to the seller.","Put the change and the receipt in your wallet.","Choose what to buy."],"dok":2,"skill":"sequence"},{"q":"Which is the BEST title for steps about saving for a bike?","answer":"How to Save for a New Bike","explanation":"How to + goal.","explanation_ar":"العنوان الأفضل.","options":["Bikes","How to Save for a New Bike","My Bike Is Red","Once Upon a Bike"],"dok":3,"skill":"titles"},{"q":"A friend follows your steps and asks, *How much money?* What should you change?","answer":"Add the exact amount to the step.","explanation":"Revising for clarity.","explanation_ar":"أضف المبلغ الدقيق.","options":["Remove the numbers.","Make the step longer with two actions.","Add a joke.","Add the exact amount to the step."],"dok":3,"skill":"revising"}],"images":[{"id":"IMG-RW-L04-U4-LS4-V01","prompt":"Picture for the word 'subtract': 50 – 35 = 15 written on paper"},{"id":"IMG-RW-L04-U4-LS4-V02","prompt":"Picture for the word 'total': a receipt with 'TOTAL' underlined"},{"id":"IMG-RW-L04-U4-LS4-V03","prompt":"Picture for the word 'note': a 50-riyal note"},{"id":"IMG-RW-L04-U4-LS4-V04","prompt":"Picture for the word 'counter': a shop counter with a cash machine"},{"id":"IMG-RW-L04-U4-LS4-V05","prompt":"Picture for the word 'politely': a child speaking kindly to a seller"},{"id":"IMG-RW-L04-U4-LS4-V06","prompt":"Picture for the word 'imperative': a sign that says 'STOP!'"},{"id":"IMG-RW-L04-U4-LS4-V07","prompt":"Picture for the word 'mistake': a red cross on a wrong sum"},{"id":"IMG-RW-L04-U4-LS4-01","prompt":"Omar checking his change at a shop counter."},{"id":"IMG-RW-L04-U4-LS4-02","prompt":"A vague step and a clear step side by side."},{"id":"IMG-RW-L04-U4-LS4-03","prompt":"Imperative verb signs."}],"audio":[{"id":"AUD-RW-L04-U4-LS4-V01","script":"subtract. Subtract 35 from 50."},{"id":"AUD-RW-L04-U4-LS4-V02","script":"total. The total is 35 riyals."},{"id":"AUD-RW-L04-U4-LS4-V03","script":"note. He paid with a 50-riyal note."},{"id":"AUD-RW-L04-U4-LS4-V04","script":"counter. Check your change at the counter."},{"id":"AUD-RW-L04-U4-LS4-V05","script":"politely. Politely show the seller the receipt."},{"id":"AUD-RW-L04-U4-LS4-V06","script":"imperative. Each step starts with an imperative verb."},{"id":"AUD-RW-L04-U4-LS4-V07","script":"mistake. Anyone can make a mistake."},{"id":"AUD-RW-L04-U4-LS4-T1","script":"Sellers are usually honest, but anyone can make a mistake. Checking your change takes only a few seconds, and it keeps your budget safe. **You need:** your money, the receipt and a little math. **1.** Before you pay, read the total price on the receipt or on the screen. **2.** Look carefully at how much money you give the seller. **3.** Subtract the price from the money you gave. For example, 50 – 35 = 15 riyals. **4.** Count the change the seller gives you, starting with the biggest note. **5.** Compare your answer with the change in your hand. If they are the same, say \"Thank you!\" **6.** If they are different, politely show the seller the receipt and your math. **7.** Put the change and the receipt in your wallet before you walk away. **Tip:** Always check your change at the counter. It is much harder to fix a mistake later at home!"},{"id":"AUD-RW-L04-U4-LS4-VID","script":"Did you get the right change? Omar shows you how to check – in seven clear steps! 1. Before you pay, read the total price… Start with a bossy verb: Read! Count! Compare! Put! One action per step, with exact details: how much, where, how. Always check your change at the counter!"}]},{"id":"RW-L04-U4-LS5","title":"Writing Workshop: How to Plan a Shopping Trip","lesson_type":"writing_workshop","objectives":["plan a how-to text with the How-To Planner (title, introduction, You need, steps, tip)","write a procedural text of 6–8 clear numbered steps: How to Plan a Shopping Trip","test, revise, edit and publish the steps as a 'Smart Shopper' card"],"objectives_ar":["التخطيط لنص إرشادي بمخطط النص الإرشادي.","كتابة نص إرشادي من 6–8 خطوات مرقّمة واضحة: كيف تخطط لرحلة تسوق.","اختبار الخطوات وتحسينها وتدقيقها ونشرها في بطاقة «المتسوّق الذكي»."],"success_criteria":["My introduction tells the problem the steps will solve.","My steps are in order, start with bossy verbs and have one action each.","My steps include exact details, and I added a useful tip."],"success_criteria_ar":["مقدمتي تذكر المشكلة التي ستحلها الخطوات.","خطواتي مرتبة وتبدأ بأفعال أمر وفي كل منها فعل واحد.","خطواتي فيها تفاصيل دقيقة وأضفت نصيحة مفيدة."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"plan","pos":"verb / noun","ipa":"/plæn/","definition":"to decide what you will do; a list of things you will do","arabic":"يخطط / خطة","example":"Plan your shopping before you go.","image_id":"IMG-RW-L04-U4-LS5-V01","audio_id":"AUD-RW-L04-U4-LS5-V01","tier":"core"},{"word":"list","pos":"noun","ipa":"/lɪst/","definition":"words written one under another","arabic":"قائمة","example":"Write a shopping list.","image_id":"IMG-RW-L04-U4-LS5-V02","audio_id":"AUD-RW-L04-U4-LS5-V02","tier":"core"},{"word":"reusable","pos":"adjective","ipa":"/riˈjuzəbəl/","definition":"can be used again and again","arabic":"قابل لإعادة الاستخدام","example":"Take a reusable bag to the shop.","image_id":"IMG-RW-L04-U4-LS5-V03","audio_id":"AUD-RW-L04-U4-LS5-V03","tier":"core"},{"word":"stick to","pos":"phrasal verb","ipa":"/stɪk tu/","definition":"to follow a plan and not change it","arabic":"يلتزم بـ","example":"Make a list and stick to it.","image_id":"IMG-RW-L04-U4-LS5-V04","audio_id":"AUD-RW-L04-U4-LS5-V04","tier":"core"},{"word":"cross off","pos":"phrasal verb","ipa":"/krɔs ɔf/","definition":"to draw a line through something on a list","arabic":"يشطب","example":"Cross off each item when you buy it.","image_id":"IMG-RW-L04-U4-LS5-V05","audio_id":"AUD-RW-L04-U4-LS5-V05","tier":"core"},{"word":"flyer","pos":"noun","ipa":"/ˈflaɪər/","definition":"a small printed paper that shows prices or news","arabic":"منشور إعلاني","example":"Compare prices in the shop flyers.","image_id":"IMG-RW-L04-U4-LS5-V06","audio_id":"AUD-RW-L04-U4-LS5-V06","tier":"core"},{"word":"procedural","pos":"adjective","ipa":"/prəˈsidʒərəl/","definition":"explaining how to do something step by step","arabic":"إجرائي / إرشادي","example":"A recipe is a procedural text.","image_id":"IMG-RW-L04-U4-LS5-V07","audio_id":"AUD-RW-L04-U4-LS5-V07","tier":"core"}],"explanation":{"text":"A **procedural (how-to) text** teaches the reader to do something step by step. It has a **title** (How to…), an **introduction** (the problem it solves), a **You need** list, **numbered steps** and a **tip** or warning.\n\nUse the **planning cards**: first decide **what you need** and **your budget**, then **compare prices** and **estimate** the total. Turn each idea into **one clear step** with a **bossy verb** and **exact details**.\n\n**Test your steps!** A partner reads them and acts them out. If your partner asks a question (How much? Where? When?), add the missing detail.","examples":["Title: ***How to Plan a Shopping Trip***","Introduction: ***Do you come home from the shop with things you didn't need? Planning your trip can solve this problem.***","You need: ***paper, a pencil, your budget and a reusable bag***","Step: ***1. Check the kitchen to see what you already have.***","Step with detail: ***3. Decide on your budget – for example, 100 riyals.***","Step with comparing: ***4. Compare the prices in two shops or in their flyers.***","Step with math: ***5. Estimate the total and cross off anything you can't afford.***","Last step: ***8. At home, put the shopping away and keep the receipts.***","Tip: ***Never go shopping when you are hungry – you will want to buy everything!***"],"common_errors":["✗ No introduction. → ✓ Add one or two sentences about the problem. (Tell the reader **why**.)","✗ Steps without numbers. → ✓ Number every step. (Numbers show order.)","✗ Go shopping and buy things and come home. → ✓ Split into three steps. (One action per step.)","✗ Buy some food. → ✓ Buy only the things on your list. (Exact details.)","✗ You should to write a list. → ✓ Write a list. (Bossy verb first.)","✗ Steps in the wrong order (buy before list). → ✓ Plan first, then shop. (Check the order.)","✗ Copying Grandpa's tips word for word. → ✓ Turn each tip into your own clear step. (Own words.)"],"arabic":"النص الإجرائي (الإرشادي) يعلّم القارئ عمل شيء خطوة بخطوة، وفيه عنوان (How to…) ومقدمة تذكر المشكلة وقائمة أدوات وخطوات مرقّمة ونصيحة أو تحذير.\n\nاستخدم بطاقات التخطيط: حدّد ما تحتاجه وميزانيتك، ثم قارن الأسعار وقدّر المجموع، وحوّل كل فكرة إلى خطوة واضحة بفعل أمر وتفاصيل دقيقة.\n\nاختبر خطواتك: يقرؤها زميلك وينفذها؛ إذا سأل سؤالًا (كم؟ أين؟ متى؟) فأضف التفصيل الناقص.\n\nلا تنسخ نصائح الجد كما هي، بل حوّلها إلى خطوات بكلماتك."},"video":{"script":[{"time":"00:00–00:20","narration":"Oops! A bag full of sweets – and no bread for the picnic! Let's plan better.","on_screen":"How to Plan a Shopping Trip 🛒","visual":"A boy empties a bag of sweets on a picnic blanket; the family looks surprised."},{"time":"00:20–01:00","narration":"Read the planning cards: the picnic list, two shops' prices and Grandpa's tips.","on_screen":"Card A · Card B · Card C","visual":"Three cards slide in; prices are compared with arrows."},{"time":"01:00–01:45","narration":"Plan with the How-To Planner: title, introduction, You need, steps and a tip.","on_screen":"How-To Planner 📋","visual":"A planner fills in box by box."},{"time":"01:45–02:30","narration":"1. Check the kitchen… 2. Write a shopping list… 3. Decide on your budget…","on_screen":"Bossy verb + one action + details","visual":"Each step appears with an icon as Sami and Noura follow it."},{"time":"02:30–03:00","narration":"Test your steps with a partner, fix them and publish your Smart Shopper card!","on_screen":"Smart Shopper 🏅","visual":"A finished card with a gold star badge."}],"captions_ar":["أوه! كيس مليء بالحلوى ولا خبز للنزهة! لنخطط بشكل أفضل.","اقرأ بطاقات التخطيط: قائمة النزهة وأسعار متجرين ونصائح الجد.","خطّط بالمخطط: العنوان والمقدمة والأدوات والخطوات والنصيحة.","1. تفقّد المطبخ… 2. اكتب قائمة التسوق… 3. حدّد ميزانيتك…","اختبر خطواتك مع زميل، وصحّحها، وانشر بطاقة المتسوّق الذكي!"],"voice":"Narrator: American English, upbeat female presenter, speed 0.90. Grandpa Saleh gives tips."},"texts":[{"type":"model","title":"Shopping Trip Planning Cards","body":"**Card A – The Family Picnic** · Event: a family picnic on Friday · Need: bread, cheese, fruit, juice, napkins · Already at home: dates and water · Budget: 100 riyals\n\n**Card B – Two Shops, Two Prices** · Bread: 6 riyals (Shop 1) / 5 riyals (Shop 2) · Cheese: 25 / 20 · Fruit: 30 / 35 · Juice: 18 / 15 · Napkins: 7 / 5\n\n**Card C – Grandpa's Shopping Tips** · Check what you already have · Make a list and stick to it · Compare prices · Estimate the total before you go · Take a reusable bag · Keep the receipts","word_count":85,"audio_id":"AUD-RW-L04-U4-LS5-T1","id":"TXT-RW-L04-U4-LS5-1","genre":"planning cards","role":"model","difficulty":"450L–600L","glossary":[],"annotations":["**Card A** tells you **what** you need and your **budget**.","**Card B** helps you **compare prices** and **estimate** the total. (Cheapest total: 5 + 20 + 30 + 15 + 5 = 75 riyals.)","**Card C** gives ideas for your **steps** and your **tip**. Turn each idea into a clear step with a **bossy verb** and **exact details**."]}],"activities":[{"id":"RW-L04-U4-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the planning cards. Choose the answer.","instructions_ar":"اقرأ بطاقات التخطيط واختر الإجابة.","items":[{"q":"What is the budget for the family picnic?","answer":"100 riyals","explanation":"Card A.","explanation_ar":"100 ريال.","options":["100 riyals","75 riyals","50 riyals","150 riyals"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Which items does the family ALREADY have at home?","answer":"dates and water","explanation":"Card A.","explanation_ar":"التمر والماء.","options":["bread and cheese","dates and water","fruit and juice","napkins and bread"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Which shop sells cheese for less?","answer":"Shop 2","explanation":"Card B: 25 / 20.","explanation_ar":"المتجر الثاني.","options":["Shop 2","Shop 1","Both are the same price.","Neither shop sells cheese."],"dok":1,"skill":"compare","stage":"controlled"},{"q":"Where is the fruit cheaper?","answer":"Shop 1","explanation":"Card B: 30 / 35.","explanation_ar":"المتجر الأول.","options":["Shop 2","Both are the same price.","at home","Shop 1"],"dok":2,"skill":"compare","stage":"controlled"},{"q":"What is the cheapest total for all five items?","answer":"75 riyals","explanation":"5 + 20 + 30 + 15 + 5.","explanation_ar":"75 ريالًا.","options":["86 riyals","100 riyals","75 riyals","60 riyals"],"dok":2,"skill":"estimate","stage":"controlled"},{"q":"Which of Grandpa's tips helps you stop buying things you don't need?","answer":"Make a list and stick to it.","explanation":"Card C.","explanation_ar":"اكتب قائمة والتزم بها.","options":["Take a reusable bag.","Keep the receipts.","Check what you already have.","Make a list and stick to it."],"dok":2,"skill":"key details","stage":"controlled"}]},{"id":"RW-L04-U4-LS5-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Plan the how-to text. Choose.","instructions_ar":"خطّط للنص الإرشادي: اختر.","items":[{"q":"Which is the BEST title for the shopping-trip text?","answer":"How to Plan a Shopping Trip","explanation":"How to + goal.","explanation_ar":"العنوان الأفضل.","options":["Shopping","My Picnic Was Fun","How to Plan a Shopping Trip","The Big Shop"],"dok":1,"skill":"titles","stage":"guided"},{"q":"Which sentence is the BEST introduction for the shopping-trip text?","answer":"Do you come home with things you didn't need? Planning your trip can solve this problem.","explanation":"Problem + solution.","explanation_ar":"المقدمة الأفضل.","options":["1. Check the kitchen.","I like shopping with my uncle.","Do you come home with things you didn't need? Planning your trip can solve this problem.","Tip: Don't shop when you are hungry."],"dok":2,"skill":"introductions","stage":"guided"},{"q":"Which step should come FIRST in planning a shopping trip?","answer":"Check the kitchen to see what you already have.","explanation":"Order.","explanation_ar":"الخطوة الأولى.","options":["Put the shopping away.","Check the kitchen to see what you already have.","Check your change.","Keep the receipts."],"dok":2,"skill":"sequence","stage":"guided"},{"q":"Which step about the budget gives an exact detail?","answer":"Decide on your budget – for example, 100 riyals.","explanation":"Detail.","explanation_ar":"تفصيل دقيق.","options":["Think about money.","Have a budget or something.","Money is important.","Decide on your budget – for example, 100 riyals."],"dok":2,"skill":"details","stage":"guided"},{"q":"Which tip from Card C becomes this step: *Take your list, your money and a cloth bag to the shop*?","answer":"Take a reusable bag.","explanation":"Tip → step.","explanation_ar":"خذ كيسًا قابلًا لإعادة الاستخدام.","options":["Compare prices.","Take a reusable bag.","Keep the receipts.","Estimate the total."],"dok":2,"skill":"paraphrasing","stage":"guided"},{"q":"Your partner reads *Buy the things* and asks, *Which things?* How should you fix the step?","answer":"Buy only the things on your list.","explanation":"Testing → revising.","explanation_ar":"أضف التفصيل.","options":["Buy only the things on your list.","Buy the things quickly.","Buy everything in the shop.","Remove the step."],"dok":3,"skill":"revising","stage":"guided"}]},{"id":"RW-L04-U4-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your text with the How-To Planner.","instructions_ar":"خطط لنصك بمخطط النص الإرشادي.","items":[{"q":"Title and introduction – what problem do your steps solve?","answer":"How to Plan a Shopping Trip. Do you come home without the things you need? Planning your trip can solve this problem.","explanation":"Title + introduction.","explanation_ar":"عنوان + مقدمة.","dok":1,"skill":"planning","stage":"freer"},{"q":"You need – list the things the reader needs.","answer":"paper, a pencil, your budget and a reusable bag","explanation":"You need.","explanation_ar":"الأدوات.","dok":1,"skill":"planning","stage":"freer"},{"q":"Steps 1–4 – write notes with a bossy verb for each.","answer":"check the kitchen; write a list; decide the budget (100 riyals); compare prices","explanation":"Steps 1–4.","explanation_ar":"الخطوات 1–4.","dok":2,"skill":"planning","stage":"freer"},{"q":"Steps 5–8 and a tip – write notes.","answer":"estimate the total; take the list and a bag; buy only list items; keep receipts – Tip: don't shop when hungry","explanation":"Steps 5–8 + tip.","explanation_ar":"الخطوات 5–8 + نصيحة.","dok":2,"skill":"planning","stage":"freer"}]},{"id":"RW-L04-U4-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write, test, revise and publish your procedural text.","instructions_ar":"اكتب نصك واختبره وحسّنه وانشره.","items":[{"q":"Write your title, introduction and You need list.","answer":"How to Plan a Shopping Trip. Do you come home with things you didn't need? Planning your trip can solve this problem. You need: paper, a pencil, your budget and a reusable bag.","explanation":"Opening parts.","explanation_ar":"الأجزاء الأولى.","dok":2,"skill":"writing","stage":"production"},{"q":"Write steps 1–4.","answer":"1. Check the kitchen to see what you already have. 2. Write a list of only the things you need. 3. Decide on your budget – for example, 100 riyals. 4. Compare the prices in two shops.","explanation":"Steps 1–4.","explanation_ar":"الخطوات 1–4.","dok":2,"skill":"writing","stage":"production"},{"q":"Write steps 5–8 and your tip.","answer":"5. Estimate the total and cross off anything you can't afford. 6. Take your list, your money and a bag. 7. Buy only the things on your list. 8. Keep the receipts. Tip: Never shop when you are hungry!","explanation":"Steps 5–8 + tip.","explanation_ar":"الخطوات 5–8 + نصيحة.","dok":2,"skill":"writing","stage":"production"},{"q":"Write one step your partner tested and you improved (before → after).","answer":"Before: 4. Look at prices. After: 4. Compare the prices of each item in two shops.","explanation":"Revision.","explanation_ar":"تحسين.","dok":3,"skill":"revising","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L04-U4-LS5-ORG","type":"organizer","organizer":"How-To Planner","instructions":"Organizer: Use the planning cards. Write short notes in each box.","items":[{"q":"Title – How to …","answer":"How to Plan a Shopping Trip"},{"q":"Introduction – the problem the steps solve","answer":"people come home with things they didn't need – planning solves this"},{"q":"You need","answer":"paper, a pencil, your budget, a reusable bag"},{"q":"Steps 1–4 (bossy verb + one action + details)","answer":"check the kitchen; write a list; decide the budget (100 riyals); compare prices"},{"q":"Steps 5–8","answer":"estimate the total and cross off extras; take list, money, bag; buy only list items and check change; put shopping away and keep receipts"},{"q":"Tip or warning","answer":"never shop when you are hungry"}]},{"id":"RW-L04-U4-LS5-WR","type":"writing","instructions":"Writing: Write a procedural text called 'How to Plan a Shopping Trip'. Include a title, an introduction, a You need list, 6–8 clear numbered steps and a tip. Write a procedural text called 'How to Plan a Shopping Trip'. Include a title, an introduction, a You need list, 6–8 clear numbered steps and a tip.","instructions_ar":"اكتب نصًا إجرائيًا بعنوان «كيف تخطط لرحلة تسوق» فيه عنوان ومقدمة وقائمة أدوات و6–8 خطوات مرقّمة واضحة ونصيحة.","prompt":"Write a procedural text called 'How to Plan a Shopping Trip'. Include a title, an introduction, a You need list, 6–8 clear numbered steps and a tip.","checklist":["My title starts with How to.","My introduction tells the problem the steps solve.","I wrote a You need list.","I wrote 6–8 steps in the correct order with numbers.","Each step starts with a bossy verb (or a time phrase or if-clause and then a verb).","Each step has one action and exact details.","I added a useful tip or warning.","I checked spelling, capital letters and periods."],"rubric_id":"RW-RUBRIC-5T","min_words":90,"max_words":170,"organizer":"How-To Planner (title – introduction – You need – steps 1–4 – steps 5–8 – tip)","items":[{"q":"Write a procedural text called 'How to Plan a Shopping Trip'. Include a title, an introduction, a You need list, 6–8 clear numbered steps and a tip.","answer":"How to Plan a Shopping Trip. Do you come home from the shop with things you didn't need and without the things you did need? Planning your trip can solve this problem. You need: paper, a pencil, your budget and a reusable bag. 1. Check the kitchen to see what you already have. 2. Write a shopping list of only the things you need. 3. Decide on your budget – for example, 100 riyals. 4. Compare the prices in two shops or in their flyers. 5. Estimate the total and cross off anything you can't afford. 6. Take your list, your money and a reusable bag to the shop. 7. Buy only the things on your list, and check your change. 8. At home, put the shopping away and keep the receipts. Tip: Never go shopping when you are hungry – you will want to buy everything!","_w":{"checklist":["My title starts with How to.","My introduction tells the problem the steps solve.","I wrote a You need list.","I wrote 6–8 steps in the correct order with numbers.","Each step starts with a bossy verb (or a time phrase or if-clause and then a verb).","Each step has one action and exact details.","I added a useful tip or warning.","I checked spelling, capital letters and periods."],"min":90,"max":170}}]}],"game":{"name":"Smart Shopper Challenge","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Shopping cart: the child follows a step list – check the kitchen, make a list, compare two shops, estimate, buy. Staying inside the budget earns a Smart Shopper badge; buying extra sweets makes the cart beep.","Each team gets a picnic list and 100 play riyals.","Teams follow their written steps: check, list, compare, estimate.","Teams 'buy' items from the two class shops and keep the receipts.","Teams show their receipts and change.","Inside the budget = 3 points; cheapest total = 2 bonus points; clear steps = 2 points."],"data":[]},"exit_quiz":[{"q":"What does a *procedural* text do?","answer":"explains how to do something step by step","explanation":"Procedural.","explanation_ar":"يشرح خطوات عمل شيء.","options":["tells a story with characters","gives only opinions","explains how to do something step by step","describes a person's life"],"dok":1,"skill":"genre"},{"q":"*Make a list and **stick to** it.* *Stick to* means ___.","answer":"follow and not change","explanation":"Phrasal verb.","explanation_ar":"التزم بها.","options":["glue on paper","follow and not change","throw away","forget"],"dok":1,"skill":"vocabulary"},{"q":"A cloth bag you can use again and again is ___.","answer":"reusable","explanation":"Reusable.","explanation_ar":"قابل لإعادة الاستخدام.","options":["reusable","expensive","procedural","crowded"],"dok":1,"skill":"vocabulary"},{"q":"Which part of a how-to text tells the problem the steps will solve?","answer":"the introduction","explanation":"Structure.","explanation_ar":"المقدمة.","options":["the You need list","step 8","the tip","the introduction"],"dok":1,"skill":"text structure"},{"q":"Which step about the shopping list is written correctly?","answer":"Write a list of only the things you need.","explanation":"Bossy verb first.","explanation_ar":"صحيحة.","options":["Write a list of only the things you need.","You should to write a list.","Writing a list of things.","A list you write."],"dok":2,"skill":"imperatives"},{"q":"Which step should come right AFTER *Compare the prices in two shops*?","answer":"Estimate the total and cross off anything you can't afford.","explanation":"Order.","explanation_ar":"تقدير المجموع.","options":["Check the kitchen.","Put the shopping away.","Estimate the total and cross off anything you can't afford.","Write the title."],"dok":2,"skill":"sequence"},{"q":"Why should you check the kitchen BEFORE writing your list?","answer":"so you don't buy things you already have","explanation":"Purpose.","explanation_ar":"حتى لا تشتري ما لديك.","options":["so the kitchen is clean","so you can eat first","so the list is longer","so you don't buy things you already have"],"dok":2,"skill":"reasons"},{"q":"Which tip would be MOST useful at the end of the shopping-trip text?","answer":"Never go shopping when you are hungry.","explanation":"Useful tip.","explanation_ar":"النصيحة الأنفع.","options":["Shops have doors.","Bread is made of flour.","My uncle likes juice.","Never go shopping when you are hungry."],"dok":2,"skill":"tips"},{"q":"How do you TEST your how-to text?","answer":"A partner follows the steps and asks about anything unclear.","explanation":"Testing.","explanation_ar":"يتّبع زميلك الخطوات.","options":["You read it once silently.","A partner follows the steps and asks about anything unclear.","You count the words.","You make the title bigger."],"dok":3,"skill":"revising"},{"q":"Using Card B, how much do you save by buying juice at Shop 2 instead of Shop 1?","answer":"3 riyals","explanation":"18 – 15.","explanation_ar":"3 ريالات.","options":["3 riyals","15 riyals","18 riyals","33 riyals"],"dok":3,"skill":"apply"}],"images":[{"id":"IMG-RW-L04-U4-LS5-V01","prompt":"Picture for the word 'plan': a child writing a plan"},{"id":"IMG-RW-L04-U4-LS5-V02","prompt":"Picture for the word 'list': a shopping list on a notepad"},{"id":"IMG-RW-L04-U4-LS5-V03","prompt":"Picture for the word 'reusable': a cloth shopping bag"},{"id":"IMG-RW-L04-U4-LS5-V04","prompt":"Picture for the word 'stick to': a child walking past toys with a list in hand"},{"id":"IMG-RW-L04-U4-LS5-V05","prompt":"Picture for the word 'cross off': a list with lines through some items"},{"id":"IMG-RW-L04-U4-LS5-V06","prompt":"Picture for the word 'flyer': a colorful supermarket flyer"},{"id":"IMG-RW-L04-U4-LS5-V07","prompt":"Picture for the word 'procedural': a numbered list of steps with icons"},{"id":"IMG-RW-L04-U4-LS5-01","prompt":"A student's Smart Shopper card."},{"id":"IMG-RW-L04-U4-LS5-02","prompt":"Three shopping trip planning cards."},{"id":"IMG-RW-L04-U4-LS5-03","prompt":"A how-to planner organizer."}],"audio":[{"id":"AUD-RW-L04-U4-LS5-V01","script":"plan. Plan your shopping before you go."},{"id":"AUD-RW-L04-U4-LS5-V02","script":"list. Write a shopping list."},{"id":"AUD-RW-L04-U4-LS5-V03","script":"reusable. Take a reusable bag to the shop."},{"id":"AUD-RW-L04-U4-LS5-V04","script":"stick to. Make a list and stick to it."},{"id":"AUD-RW-L04-U4-LS5-V05","script":"cross off. Cross off each item when you buy it."},{"id":"AUD-RW-L04-U4-LS5-V06","script":"flyer. Compare prices in the shop flyers."},{"id":"AUD-RW-L04-U4-LS5-V07","script":"procedural. A recipe is a procedural text."},{"id":"AUD-RW-L04-U4-LS5-T1","script":"**Card A – The Family Picnic** · Event: a family picnic on Friday · Need: bread, cheese, fruit, juice, napkins · Already at home: dates and water · Budget: 100 riyals **Card B – Two Shops, Two Prices** · Bread: 6 riyals (Shop 1) / 5 riyals (Shop 2) · Cheese: 25 / 20 · Fruit: 30 / 35 · Juice: 18 / 15 · Napkins: 7 / 5 **Card C – Grandpa's Shopping Tips** · Check what you already have · Make a list and stick to it · Compare prices · Estimate the total before you go · Take a reusable bag · Keep the receipts"},{"id":"AUD-RW-L04-U4-LS5-VID","script":"Oops! A bag full of sweets – and no bread for the picnic! Let's plan better. Read the planning cards: the picnic list, two shops' prices and Grandpa's tips. Plan with the How-To Planner: title, introduction, You need, steps and a tip. 1. Check the kitchen… 2. Write a shopping list… 3. Decide on your budget… Test your steps with a partner, fix them and publish your Smart Shopper card!"}]}],"unit_test":[{"q":"The sign on the lantern says 30 riyals. That is its ___.","answer":"price","explanation":"Price.","explanation_ar":"السعر.","options":["price","wallet","change","customer"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"*The gold watch was **expensive**, but the plastic one was cheap.* *Expensive* means ___.","answer":"costing a lot of money","explanation":"Opposite of cheap.","explanation_ar":"غالٍ.","options":["costing very little","very old","very small","costing a lot of money"],"dok":1,"skill":"antonym clues","_part":"Part A – Vocabulary"},{"q":"Five people were waiting to pay at the counter. They were ___.","answer":"customers","explanation":"Customer.","explanation_ar":"زبائن.","options":["sellers","customers","receipts","budgets"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Keep the ___ in case you need to return the shoes.","answer":"receipt","explanation":"Receipt.","explanation_ar":"الإيصال.","options":["receipt","coin","price","trade"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"I paid with a 20-riyal note for a 12-riyal book. My ___ was 8 riyals.","answer":"change","explanation":"20 – 12.","explanation_ar":"الباقي.","options":["budget","total","price","change"],"dok":2,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Our class made a ___ for the trip: 50 riyals for food and 30 for tickets.","answer":"budget","explanation":"Budget.","explanation_ar":"ميزانية.","options":["receipt","wallet","budget","lane"],"dok":1,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"*Unlike his sister, who saves every riyal, Fahad is a **spender**.* A *spender* is someone who ___.","answer":"uses money quickly","explanation":"Opposite of saves.","explanation_ar":"مُسرف في الإنفاق.","options":["keeps money in a jar","uses money quickly","sells things","counts coins"],"dok":2,"skill":"antonym clues","_part":"Part A – Vocabulary"},{"q":"Before we went shopping, Mother ___ that the food would cost about 70 riyals.","answer":"estimated","explanation":"Estimate.","explanation_ar":"قدّرت.","options":["traded","afforded","estimated","subtracted"],"dok":2,"skill":"vocabulary","_part":"Part A – Vocabulary"},{"q":"Which step for the lemonade stall starts with an imperative verb?","answer":"Write the price on a big, bright sign.","explanation":"Bossy verb first.","explanation_ar":"يبدأ بفعل أمر.","options":["Write the price on a big, bright sign.","The price is on a sign.","Writing the price on a sign.","You are writing the price."],"dok":1,"skill":"imperatives","_part":"Part D – Writing skills"},{"q":"Which step for making lemonade gives the clearest details?","answer":"Squeeze four lemons into a large jug.","explanation":"Exact details.","explanation_ar":"الأوضح.","options":["Do the lemons.","Put some stuff in a jug.","Squeeze four lemons into a large jug.","Lemons are yellow."],"dok":2,"skill":"details","_part":"Part D – Writing skills"},{"q":"Which step for the stall should be split into two steps?","answer":"Count the coins and put them in the box and clean the table.","explanation":"One action per step.","explanation_ar":"تحتاج إلى تقسيم.","options":["Count the coins.","Count the coins and put them in the box and clean the table.","Clean the table.","Put the coins in the box."],"dok":2,"skill":"one action per step","_part":"Part D – Writing skills"},{"q":"Which order of steps for making lemonade makes sense?","answer":"Squeeze the lemons. → Add water and sugar. → Stir well. → Add ice.","explanation":"Logical order.","explanation_ar":"الترتيب المنطقي.","options":["Add ice. → Stir well. → Squeeze the lemons.","Stir well. → Squeeze the lemons. → Add water.","Add water and sugar. → Add ice. → Squeeze the lemons.","Squeeze the lemons. → Add water and sugar. → Stir well. → Add ice."],"dok":2,"skill":"sequence","_part":"Part D – Writing skills"},{"q":"Which is the BEST introduction for *How to Run a Charity Stall*?","answer":"Do you want to help others at the school fair? These steps will help your stall raise money.","explanation":"Problem / goal.","explanation_ar":"المقدمة الأفضل.","options":["1. Make a sign.","Do you want to help others at the school fair? These steps will help your stall raise money.","Lemons grow on trees.","Tip: Smile at customers."],"dok":2,"skill":"introductions","_part":"Part D – Writing skills"},{"q":"Which is the most useful TIP for a charity stall?","answer":"Check the prices at other stalls before you choose yours.","explanation":"Useful tip.","explanation_ar":"النصيحة الأنفع.","options":["Stalls are made of wood.","My sister likes lemonade.","The fair is on Thursday.","Check the prices at other stalls before you choose yours."],"dok":3,"skill":"tips","_part":"Part D – Writing skills"}],"unit_writing":{"task":"Write a procedural text called 'How to Run a Stall at a School Charity Fair'. Include a title, an introduction, a You need list, 6–8 clear numbered steps and a tip. Use ideas from Layla's Lemonade Plan.","model":"How to Run a Stall at a School Charity Fair. Do you want to help people in need? A stall at the school charity fair is a fun way to raise money. You need: a table, the things you will sell, a big sign, a money box and a notebook. 1. Choose one thing to sell, such as lemonade or cookies. 2. Check the prices at other stalls before you choose your price. 3. Write the price on a big, bright sign. 4. Set up your table early in a place where people can see it. 5. Smile and greet every customer. 6. Give the correct change and write each sale in your notebook. 7. At the end of the day, count the money carefully with a teacher. 8. Give all the money to the charity. Tip: If nobody is buying, look around and change your plan, just like Layla did!","marks":20}});
